/* GameMog racing engine — generated by scripts/build-engine.mjs. Do not edit.
 *
 * Reads a validated WorldSpec from window.__WORLD__ and boots a race into
 * <canvas>. No part of a WorldSpec is executed; it only fills numbers, colours,
 * names and counts that this file already knew how to use.
 */
(function(){
const __W = window.__WORLD__;
if (!__W) { document.body.innerHTML = '<p style="font:16px sans-serif;padding:40px">No world supplied.</p>'; return; }

/* ============================================================================
   MUSE SPRINT — a single-file 3D rhythm footrace through the Hollow.
   Tap SPACE to stride. Find the cadence. Beat the fuzzlings.
   ========================================================================== */

/* ---------------------------------------------------------------- loader -- */
const CDN = __W.runtime.threeSources;
function loadThree(i){
  return new Promise((res, rej) => {
    if (i >= CDN.length) return rej(new Error('three.js unavailable'));
    const s = document.createElement('script');
    s.src = CDN[i];
    s.onload = () => (window.THREE ? res() : loadThree(i + 1).then(res, rej));
    s.onerror = () => loadThree(i + 1).then(res, rej);
    document.head.appendChild(s);
  });
}
loadThree(0).then(() => {
  try { boot(); }
  catch (err) {
    console.error('[gamemog] engine failed to boot', err);
    document.getElementById('loading').innerHTML =
      '<div style="text-align:center;padding:30px;line-height:1.7;max-width:640px">' +
      '<b>This world could not start.</b><br><span style="opacity:.7;font-size:13px">' +
      String(err && err.message || err).replace(/[<>]/g, '') + '</span></div>';
    try { parent.postMessage({ source: 'gamemog', type: 'error', message: String(err && err.message || err) }, '*'); } catch (e2) {}
  }
}).catch(() => {
  document.getElementById('loading').innerHTML =
    '<div style="text-align:center;padding:30px;line-height:1.7">Could not reach the three.js CDN.<br>Connect to the internet once and reload.</div>';
});

/* ------------------------------------------------------------- utilities -- */
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp  = (a, b, t) => a + (b - a) * t;
const smoothDamp = (cur, tgt, lambda, dt) => lerp(cur, tgt, 1 - Math.exp(-lambda * dt));

function mulberry(seed){
  return function(){
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rnd = mulberry(20260921);

/* value noise ------------------------------------------------------------- */
const NP = new Uint8Array(512);
(() => { const p = []; for (let i = 0; i < 256; i++) p.push(i);
  for (let i = 255; i > 0; i--) { const j = (rnd() * (i + 1)) | 0; [p[i], p[j]] = [p[j], p[i]]; }
  for (let i = 0; i < 512; i++) NP[i] = p[i & 255]; })();
const fade = t => t * t * (3 - 2 * t);
function vnoise(x, y){
  const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
  const xf = x - Math.floor(x), yf = y - Math.floor(y);
  const u = fade(xf), v = fade(yf);
  const h = (a, b) => (NP[(NP[a] + b) & 511]) / 255;
  return lerp(lerp(h(X, Y), h(X + 1, Y), u), lerp(h(X, Y + 1), h(X + 1, Y + 1), u), v);
}
function fbm(x, y, oct = 4){
  let s = 0, a = .5, f = 1;
  for (let i = 0; i < oct; i++) { s += vnoise(x * f, y * f) * a; f *= 2.03; a *= .5; }
  return s * 1.33;
}

/* ------------------------------------------------------------- constants -- */
const LAPS = __W.race.laps;
const ROAD_HALF = __W.track.roadHalf;
const LANES = __W.track.lanes;

const RACERS = __W.racers;

/* physics tuning */
const DRAG     = __W.physics.drag;
const MAXSPEED = __W.physics.maxSpeed;
const DIAL_MAX = 0.50;      // seconds represented by the full cadence dial

/* ---------------------------------------------------------------- TEMPO ----
   Borrowed straight from Tetris gravity: every lap is a level, and every level
   the band you must hit slides left and narrows. The needle on the dial is the
   falling piece; the band is where you have to lock it. You are not asked to
   tap harder each lap, you are asked to tap *tighter* — and the field speeds up
   underneath you while the rubber band that was carrying you lets go.          */
const TEMPI = __W.tempi.map(t => Object.assign({}, t));
TEMPI.forEach(t => { t.mash = t.lo * 0.60; t.cold = t.hi * 2.0; });

let TEMPO = 0;          // current level index
let T = TEMPI[0];       // live tempo the whole game reads from

/* ------------------------------------------------------------ shader bits -- */
const LIGHT_UNIFORMS = () => ({
  uLightDir: { value: new THREE.Vector3(0.44, 0.78, 0.44).normalize() },
  uLightCol: { value: new THREE.Color(__W.palette.light) },
  uSkyCol:   { value: new THREE.Color(__W.palette.skyAmbient) },
  uGndCol:   { value: new THREE.Color(__W.palette.groundAmbient) },
  uFogCol:   { value: new THREE.Color(__W.palette.fog) },
  uFogDen:   { value: __W.palette.fogDensity },
  uTime:     { value: 0 }
});

const LIGHT_GLSL = `
uniform vec3 uLightDir; uniform vec3 uLightCol; uniform vec3 uSkyCol;
uniform vec3 uGndCol; uniform vec3 uFogCol; uniform float uFogDen; uniform float uTime;
vec3 shadeIt(vec3 base, vec3 N, vec3 V, float rimAmt){
  float ndl  = clamp(dot(N, uLightDir) * 0.60 + 0.40, 0.0, 1.0);
  vec3  hemi = mix(uGndCol, uSkyCol, N.y * 0.5 + 0.5);
  vec3  col  = base * (hemi * 0.40 + uLightCol * ndl * 0.68);
  float rim  = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.5);
  col += uLightCol * rim * rimAmt;
  return col;
}
vec3 fogIt(vec3 col, float dist){
  float f = 1.0 - exp(-uFogDen * uFogDen * dist * dist);
  return mix(col, uFogCol, clamp(f, 0.0, 1.0));
}`;

/* ======================================================================== */
/*                                THE GAME                                  */
/* ======================================================================== */
function boot(){

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);

const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
/* Custom ShaderMaterials do not receive three's colour-space / tone-mapping
   injection, so every conversion is switched off and colours go straight to
   the framebuffer exactly as authored. Consistent across three versions. */
if (THREE.ColorManagement) THREE.ColorManagement.enabled = false;
if ('outputColorSpace' in renderer && THREE.LinearSRGBColorSpace) renderer.outputColorSpace = THREE.LinearSRGBColorSpace;
else if ('outputEncoding' in renderer && THREE.LinearEncoding !== undefined) renderer.outputEncoding = THREE.LinearEncoding;
renderer.toneMapping = THREE.NoToneMapping;

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(__W.palette.fog, __W.palette.fogDensity);

const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.4, 1600);
const LIGHTU = LIGHT_UNIFORMS();

addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

/* ============================== 1. THE TRACK ============================== */
const RAW = __W.track.points;
const SCALE = __W.track.scale;
const curve = new THREE.CatmullRomCurve3(
  RAW.map(p => new THREE.Vector3(p[0] * SCALE, p[1], p[2] * SCALE)), true, 'catmullrom', 0.5
);

/* arc-length lookup table */
const NS = 2400;
const CPTS = [], CUM = new Float32Array(NS + 1);
for (let i = 0; i <= NS; i++) CPTS.push(curve.getPoint(i / NS));
for (let i = 1; i <= NS; i++) CUM[i] = CUM[i - 1] + CPTS[i].distanceTo(CPTS[i - 1]);
const TOTAL = CUM[NS];
const FINISH_DIST = TOTAL * LAPS;

const _p = new THREE.Vector3(), _t = new THREE.Vector3(), _r = new THREE.Vector3(), _u = new THREE.Vector3();
const UPV = new THREE.Vector3(0, 1, 0);

function frameAt(d, out){
  let x = d % TOTAL; if (x < 0) x += TOTAL;
  let lo = 0, hi = NS;
  while (lo < hi - 1) { const m = (lo + hi) >> 1; (CUM[m] <= x) ? lo = m : hi = m; }
  const seg = CUM[lo + 1] - CUM[lo];
  const f = seg > 1e-6 ? (x - CUM[lo]) / seg : 0;
  out.pos.copy(CPTS[lo]).lerp(CPTS[lo + 1], f);
  const a = CPTS[(lo + NS - 3) % NS], b = CPTS[(lo + 4) % NS];
  out.tan.subVectors(b, a).normalize();
  out.right.crossVectors(out.tan, UPV).normalize();
  out.up.crossVectors(out.right, out.tan).normalize();
  return out;
}
const mkFrame = () => ({ pos: new THREE.Vector3(), tan: new THREE.Vector3(), right: new THREE.Vector3(), up: new THREE.Vector3() });
const FR = mkFrame();

/* curvature at a distance (for banking + AI) — scratch frames, no allocation */
const _cA = mkFrame(), _cB = mkFrame(), _cX = new THREE.Vector3();
function curvatureAt(d){
  frameAt(d - 7, _cA); frameAt(d + 7, _cB);
  _cX.crossVectors(_cA.tan, _cB.tan);
  return _cA.tan.angleTo(_cB.tan) * (_cX.y < 0 ? -1 : 1);
}

/* coarse samples for distance queries */
const COARSE = [];
for (let i = 0; i < 300; i++) COARSE.push(curve.getPoint(i / 300));
function distToTrack(x, z){
  let best = 1e9, bestY = 0;
  for (let i = 0; i < COARSE.length; i++){
    const c = COARSE[i], dx = c.x - x, dz = c.z - z;
    const d2 = dx * dx + dz * dz;
    if (d2 < best) { best = d2; bestY = c.y; }
  }
  return { d: Math.sqrt(best), y: bestY };
}

/* ============================== 2. THE SKY =============================== */
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(760, 32, 20),
  new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: { uSun: { value: new THREE.Vector3().fromArray(__W.palette.sunDir).normalize() },
                uGrade: { value: new THREE.Color(0xFFFFFF) },
                uLow:  { value: new THREE.Color(__W.palette.skyLow) },
                uMid:  { value: new THREE.Color(__W.palette.skyMid) },
                uHigh: { value: new THREE.Color(__W.palette.skyHigh) } },
    vertexShader: `varying vec3 vD; void main(){ vD = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      varying vec3 vD; uniform vec3 uSun; uniform vec3 uGrade;
      uniform vec3 uLow; uniform vec3 uMid; uniform vec3 uHigh;
      void main(){
        float h = clamp(vD.y * 0.5 + 0.5, 0.0, 1.0);
        vec3 low = uLow, mid = uMid, high = uHigh;
        vec3 col = mix(low, mid, smoothstep(0.46, 0.58, h));
        col = mix(col, high, smoothstep(0.55, 0.96, h));
        float sd = max(dot(normalize(vD), normalize(uSun)), 0.0);
        col += vec3(1.0, 0.86, 0.66) * pow(sd, 6.0) * 0.30;
        col += vec3(1.0, 0.95, 0.84) * pow(sd, 120.0) * 0.85;
        col += vec3(0.05, 0.03, 0.0) * (1.0 - h) * 0.4;
        gl_FragColor = vec4(col * uGrade, 1.0);
      }`
  })
);
sky.frustumCulled = false;
scene.add(sky);

/* fluffy clouds -------------------------------------------------------- */
function puffTexture(){
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(64, 64, 2, 64, 64, 62);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(.45, 'rgba(255,252,246,.72)');
  grad.addColorStop(1, 'rgba(255,250,240,0)');
  g.fillStyle = grad; g.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c); t.needsUpdate = true; return t;
}
const PUFF = puffTexture();
const cloudMat = new THREE.SpriteMaterial({ map: PUFF, transparent: true, opacity: .62, depthWrite: false, fog: false });
const clouds = new THREE.Group();
for (let i = 0; i < 46; i++){
  const ang = rnd() * Math.PI * 2, rad = 170 + rnd() * 330;
  const cx = Math.cos(ang) * rad, cz = Math.sin(ang) * rad;
  const cy = 52 + rnd() * 105, s = 34 + rnd() * 62;
  for (let k = 0; k < 4; k++){
    const sp = new THREE.Sprite(cloudMat.clone());
    sp.material.opacity = .30 + rnd() * .3;
    sp.position.set(cx + (rnd() - .5) * s * 1.5, cy + (rnd() - .5) * s * .32, cz + (rnd() - .5) * s * 1.5);
    const sc = s * (.55 + rnd() * .7);
    sp.scale.set(sc, sc * .62, 1);
    clouds.add(sp);
  }
}
scene.add(clouds);

/* ============================= 3. THE GROUND ============================= */
const TERR_SIZE = 460, TERR_SEG = 148;
const tgeo = new THREE.PlaneGeometry(TERR_SIZE, TERR_SIZE, TERR_SEG, TERR_SEG);
tgeo.rotateX(-Math.PI / 2);
{
  const pos = tgeo.attributes.position;
  const col = new Float32Array(pos.count * 3);
  const cMoss  = new THREE.Color(__W.palette.terrain.moss);
  const cPale  = new THREE.Color(__W.palette.terrain.pale);
  const cSand  = new THREE.Color(__W.palette.terrain.sand);
  const cRose  = new THREE.Color(__W.palette.terrain.accent);
  const tmp = new THREE.Color();
  for (let i = 0; i < pos.count; i++){
    const x = pos.getX(i), z = pos.getZ(i);
    const near = distToTrack(x, z);
    const hills = (fbm(x * .0075 + 40, z * .0075 - 20, 5) - .5) * 26
                + (fbm(x * .031, z * .031, 3) - .5) * 3.2;
    const rimDist = Math.sqrt(x * x + z * z);
    const bowl = Math.max(0, (rimDist - 130) / 105);
    let h = hills + bowl * bowl * 46;
    /* flatten into a shelf around the racing loop */
    const flat = 1 - clamp((near.d - ROAD_HALF - 2.0) / 11, 0, 1);
    h = lerp(h, near.y - 0.66, flat * flat * (3 - 2 * flat));
    h += (1 - flat) * (fbm(x * .085, z * .085, 2) - .5) * 1.1;
    pos.setY(i, h);

    const m = fbm(x * .017 + 9, z * .017 + 3, 3);
    tmp.copy(cMoss).lerp(cPale, clamp((m - .35) * 2.2, 0, 1));
    if (m < .36) tmp.lerp(cRose, clamp((.36 - m) * 2.0, 0, .45));
    tmp.lerp(cSand, clamp(1 - (near.d - ROAD_HALF) / 7.5, 0, 1) * .85);
    tmp.multiplyScalar(0.92 + fbm(x * .5, z * .5, 2) * 0.18);
    col[i * 3] = tmp.r; col[i * 3 + 1] = tmp.g; col[i * 3 + 2] = tmp.b;
  }
  tgeo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  tgeo.computeVertexNormals();
}
const groundMat = new THREE.ShaderMaterial({
  uniforms: LIGHTU,
  vertexShader: `
    varying vec3 vN; varying vec3 vC; varying vec3 vW;
    void main(){
      vN = normalize(normalMatrix * normal); vC = color;
      vec4 w = modelMatrix * vec4(position,1.0); vW = w.xyz;
      gl_Position = projectionMatrix * viewMatrix * w;
    }`,
  fragmentShader: LIGHT_GLSL + `
    varying vec3 vN; varying vec3 vC; varying vec3 vW;
    void main(){
      vec3 V = normalize(cameraPosition - vW);
      vec3 col = shadeIt(vC, normalize(vN), V, 0.06);
      gl_FragColor = vec4(fogIt(col, length(cameraPosition - vW)), 1.0);
    }`,
  vertexColors: true
});
const ground = new THREE.Mesh(tgeo, groundMat);
scene.add(ground);

/* height sampler for scattering props */
function terrainHeight(x, z){
  const near = distToTrack(x, z);
  const hills = (fbm(x * .0075 + 40, z * .0075 - 20, 5) - .5) * 26
              + (fbm(x * .031, z * .031, 3) - .5) * 3.2;
  const rimDist = Math.sqrt(x * x + z * z);
  const bowl = Math.max(0, (rimDist - 130) / 105);
  let h = hills + bowl * bowl * 46;
  const flat = 1 - clamp((near.d - ROAD_HALF - 2.0) / 11, 0, 1);
  h = lerp(h, near.y - 0.66, flat * flat * (3 - 2 * flat));
  h += (1 - flat) * (fbm(x * .085, z * .085, 2) - .5) * 1.1;
  return h;
}

/* ============================== 4. THE ROAD ============================== */
{
  const N = 900, verts = [], nors = [], uvs = [], idx = [], dists = [];
  const f = mkFrame();
  for (let i = 0; i <= N; i++){
    const d = (i / N) * TOTAL;
    frameAt(d, f);
    for (let k = 0; k <= 4; k++){
      const s = (k / 4) * 2 - 1;                // -1 .. 1
      const edge = Math.abs(s);
      const lift = 0.12 - edge * edge * 0.34;   // crowned, dipping at the verge
      verts.push(
        f.pos.x + f.right.x * s * ROAD_HALF, f.pos.y + lift, f.pos.z + f.right.z * s * ROAD_HALF
      );
      nors.push(0, 1, 0);
      uvs.push(s * 0.5 + 0.5, d / 7.0);
      dists.push(d);
    }
  }
  for (let i = 0; i < N; i++) for (let k = 0; k < 4; k++){
    const a = i * 5 + k, b = a + 5;
    idx.push(a, a + 1, b, b, a + 1, b + 1);
  }
  const rg = new THREE.BufferGeometry();
  rg.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  rg.setAttribute('normal',   new THREE.Float32BufferAttribute(nors, 3));
  rg.setAttribute('uv',       new THREE.Float32BufferAttribute(uvs, 2));
  rg.setAttribute('aDist',    new THREE.Float32BufferAttribute(dists, 1));
  rg.setIndex(idx);
  rg.computeVertexNormals();

  const roadMat = new THREE.ShaderMaterial({
    uniforms: Object.assign({}, LIGHTU, { uTotal: { value: TOTAL } }),
    vertexShader: `
      attribute float aDist;
      varying vec2 vUv; varying vec3 vN; varying vec3 vW; varying float vD;
      void main(){ vUv = uv; vD = aDist; vN = normalize(normalMatrix * normal);
        vec4 w = modelMatrix * vec4(position,1.0); vW = w.xyz;
        gl_Position = projectionMatrix * viewMatrix * w; }`,
    fragmentShader: LIGHT_GLSL + `
      uniform float uTotal;
      varying vec2 vUv; varying vec3 vN; varying vec3 vW; varying float vD;
      float h21(vec2 p){ return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453); }
      float vn(vec2 p){
        vec2 i = floor(p), f = fract(p); f = f*f*(3.0-2.0*f);
        return mix(mix(h21(i), h21(i+vec2(1,0)), f.x), mix(h21(i+vec2(0,1)), h21(i+vec2(1,1)), f.x), f.y);
      }
      void main(){
        float s = vUv.x * 2.0 - 1.0;
        float e = abs(s);
        vec3 col = vec3(0.878, 0.798, 0.641);
        col = mix(col, vec3(0.823, 0.735, 0.585), vn(vec2(vUv.x*7.0, vUv.y*7.0)) * 0.75);
        col *= 0.90 + vn(vec2(vUv.x*44.0, vUv.y*44.0)) * 0.22;

        /* lane grooves */
        float lanes = abs(fract(vUv.x * 6.0) - 0.5);
        float groove = 1.0 - smoothstep(0.0, 0.055, lanes);
        col = mix(col, vec3(0.745, 0.682, 0.553), groove * 0.55 * step(0.06, e));

        /* dashed centre line */
        float dash = step(0.55, fract(vUv.y * 2.2));
        float ctr  = 1.0 - smoothstep(0.012, 0.042, abs(s));
        col = mix(col, vec3(0.988, 0.957, 0.898), ctr * dash * 0.85);

        /* mossy verges */
        float verge = smoothstep(0.74, 1.0, e);
        col = mix(col, vec3(0.573, 0.678, 0.478), verge * (0.55 + vn(vec2(vUv.x*22.0, vUv.y*30.0)) * 0.45));
        col *= 1.0 - verge * 0.12;

        /* start / finish band — once per lap, at d = 0 */
        float fy = min(vD, uTotal - vD);
        float band = 1.0 - smoothstep(0.95, 1.30, fy);
        float check = mod(floor(vUv.x * 14.0) + floor(fy * 2.6), 2.0);
        col = mix(col, mix(vec3(0.97,0.95,0.91), vec3(0.28,0.22,0.16), check), band * 0.92);

        vec3 lit = shadeIt(col, normalize(vN), normalize(cameraPosition - vW), 0.04);
        gl_FragColor = vec4(fogIt(lit, length(cameraPosition - vW)), 1.0);
      }`
  });
  const road = new THREE.Mesh(rg, roadMat);
  road.renderOrder = 1;
  scene.add(road);
}

/* ========================= 5. FUZZLING CONSTRUCTION ====================== */
/* one merged body geometry, rigged entirely in the vertex shader:
   aPart 0 = torso/hood · 1,2 = arms · 3,4 = legs                          */
function mergeParts(entries){
  let total = 0;
  const prepped = entries.map(e => {
    let g = e.geo.clone();
    if (e.matrix) g.applyMatrix4(e.matrix);
    if (g.index) g = g.toNonIndexed();
    total += g.attributes.position.count;
    return { g, part: e.part };
  });
  const pos = new Float32Array(total * 3), nor = new Float32Array(total * 3), par = new Float32Array(total);
  let o = 0;
  for (const { g, part } of prepped){
    const c = g.attributes.position.count;
    pos.set(g.attributes.position.array, o * 3);
    nor.set(g.attributes.normal.array, o * 3);
    par.fill(part, o, o + c);
    o += c;
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  out.setAttribute('normal',   new THREE.BufferAttribute(nor, 3));
  out.setAttribute('aPart',    new THREE.BufferAttribute(par, 1));
  return out;
}

const BODY_BOT = 0.30, BODY_TOP = 1.975;
const BASE_PROFILE = [
  [0.00, 0.30], [0.24, 0.305], [0.44, 0.355], [0.60, 0.455], [0.71, 0.615],
  [0.765, 0.80], [0.778, 1.00], [0.755, 1.185], [0.708, 1.335], [0.652, 1.455],
  [0.606, 1.555], [0.567, 1.660], [0.516, 1.775], [0.424, 1.878], [0.262, 1.948],
  [0.00, 1.975]
];
const bell = (t, c, w) => Math.exp(-Math.pow((t - c) / w, 2.0));

/* Deform the shipped silhouette rather than inventing one. Every rig is a
   morph of a shape already known to read at racing speed. */
function rigMetrics(R){
  const span = BODY_TOP - BODY_BOT;
  return {
    crownY: BODY_BOT + span * R.height,
    armPivot: [0.72 * R.girth, BODY_BOT + (0.95 - BODY_BOT) * R.height],
    legPivotY: BODY_BOT + 0.15 * R.legLength,
    faceC: [0, BODY_BOT + (1.452 - BODY_BOT) * R.height, 0.135 * R.girth],
    faceR: [0.482, 0.492, 0.455].map(v => v * R.faceSize * (0.86 + 0.14 * R.girth))
  };
}

function buildBody(R){
  const span = BODY_TOP - BODY_BOT;
  const profile = BASE_PROFILE.map(([r, y]) => {
    const t = (y - BODY_BOT) / span;
    let rr = r * R.girth;
    rr *= 1 - bell(t, 0.72, 0.18) * R.headRoom * 0.34 + bell(t, 0.93, 0.13) * R.headRoom * 0.28;
    rr *= 1 + (R.slouch - 0.5) * bell(t, 0.32, 0.30) * 0.40;
    return new THREE.Vector2(Math.max(0, rr), BODY_BOT + (y - BODY_BOT) * R.height);
  });
  const torso = new THREE.LatheGeometry(profile, 34);
  torso.scale(1, 1, 0.955);

  const limb = new THREE.SphereGeometry(1, 16, 12);
  const M = () => new THREE.Matrix4();
  const parts = [{ geo: torso, part: 0 }];

  const armY = BODY_BOT + (0.620 - BODY_BOT) * R.height;
  const arm = s => M().makeTranslation(s * 0.790 * R.girth, armY, 0.020)
    .multiply(M().makeRotationZ(s * -0.21))
    .multiply(M().makeScale(0.198 * R.armGirth, 0.360 * R.armLength, 0.198 * R.armGirth));
  /* legs hang below the body; anchor the foot near the ground whatever the length */
  const legR = 0.268 * R.legLength;
  const legY = BODY_BOT - 0.35 * R.legLength + legR;
  const leg = s => M().makeTranslation(s * 0.245 * R.legStance, legY, 0.005)
    .multiply(M().makeScale(0.196 * R.girth, legR, 0.205 * R.girth));
  parts.push(
    { geo: limb, part: 1, matrix: arm(-1) }, { geo: limb, part: 2, matrix: arm(1) },
    { geo: limb, part: 3, matrix: leg(-1) }, { geo: limb, part: 4, matrix: leg(1) }
  );

  /* Toppers ride on part 0 so they inherit the fur and the body's squash. */
  const m = rigMetrics(R);
  const k = R.topperSize, crown = m.crownY;
  if (R.topper === 'ears'){
    for (const s of [-1, 1]) parts.push({ geo: limb, part: 0,
      matrix: M().makeTranslation(s * 0.30 * R.girth, crown - 0.10, -0.02)
        .multiply(M().makeRotationZ(s * -0.34))
        .multiply(M().makeScale(0.15 * k, 0.26 * k, 0.11 * k)) });
  } else if (R.topper === 'horns'){
    const cone = new THREE.ConeGeometry(1, 1, 10);
    for (const s of [-1, 1]) parts.push({ geo: cone, part: 0,
      matrix: M().makeTranslation(s * 0.26 * R.girth, crown + 0.10 * k, 0.0)
        .multiply(M().makeRotationZ(s * -0.40))
        .multiply(M().makeScale(0.13 * k, 0.40 * k, 0.13 * k)) });
  } else if (R.topper === 'antennae'){
    const stalk = new THREE.CylinderGeometry(1, 1, 1, 6);
    for (const s of [-1, 1]){
      parts.push({ geo: stalk, part: 0,
        matrix: M().makeTranslation(s * 0.16 * R.girth, crown + 0.16 * k, 0.0)
          .multiply(M().makeRotationZ(s * -0.30))
          .multiply(M().makeScale(0.028 * k, 0.34 * k, 0.028 * k)) });
      parts.push({ geo: limb, part: 0,
        matrix: M().makeTranslation(s * 0.26 * R.girth, crown + 0.33 * k, 0.0)
          .multiply(M().makeScale(0.075 * k, 0.075 * k, 0.075 * k)) });
    }
  } else if (R.topper === 'crest'){
    for (let i = 0; i < 3; i++) parts.push({ geo: limb, part: 0,
      matrix: M().makeTranslation(0, crown + (0.05 + i * 0.015) * k, (i - 1) * 0.15 * R.girth)
        .multiply(M().makeScale(0.085 * k, (0.17 - i * 0.03) * k, 0.06 * k)) });
  }

  return mergeParts(parts);
}

const FACE_C   = new THREE.Vector3(0, 1.452, 0.135);
const FACE_R   = new THREE.Vector3(0.482, 0.492, 0.455);
const FACE_DIR = new THREE.Vector3(0, 0.055, 1).normalize();
const FACE_COS = 0.845;

const FUR_VERT = `
attribute float aPart;
uniform float uPhase, uSwing, uLayer, uFurLen, uDroop;
uniform vec2 uArmPivot; uniform float uLegPivotY;
uniform vec3  uFaceC, uFaceDir; uniform float uFaceCos;
varying vec3 vN; varying vec3 vRest; varying vec3 vW; varying float vEdge;

mat3 rx(float a){ float s=sin(a), c=cos(a); return mat3(1.,0.,0., 0.,c,-s, 0.,s,c); }
mat3 rz(float a){ float s=sin(a), c=cos(a); return mat3(c,-s,0., s,c,0., 0.,0.,1.); }

void main(){
  vRest = position;
  vec3 p = position;
  vec3 n = normal;
  float sw = uSwing;

  if (aPart > 2.5) {                         /* legs */
    float side = (aPart < 3.5) ? -1.0 : 1.0;
    float ph   = uPhase + (side < 0.0 ? 0.0 : 3.14159265);
    float ang  = sin(ph) * 1.02 * sw;
    vec3 piv = vec3(0.0, uLegPivotY, 0.0);
    mat3 R = rx(ang);
    p = R * (p - piv) + piv;
    p.y += max(0.0, -cos(ph)) * 0.10 * sw;   /* knee lift on the recovery */
    n = R * n;
  } else if (aPart > 0.5) {                  /* arms */
    float side = (aPart < 1.5) ? -1.0 : 1.0;
    float ph   = uPhase + (side < 0.0 ? 3.14159265 : 0.0);
    float ang  = sin(ph) * 0.80 * sw;
    vec3 piv = vec3(side * uArmPivot.x, uArmPivot.y, 0.0);
    mat3 R = rx(ang) * rz(side * -0.40 * sw);
    p = R * (p - piv) + piv;
    n = R * n;
  } else {                                   /* torso: stride squash */
    float q = cos(uPhase * 2.0) * sw;
    p.y  = (p.y - 0.30) * (1.0 - 0.055 * q) + 0.30;
    p.xz *= 1.0 + 0.048 * q;
    n = normalize(n * vec3(1.0, 1.0 - 0.055 * q, 1.0));
  }

  /* hood opening: fur shortens towards the face (per-pixel cut in the frag) */
  vec3 fq = vRest - uFaceC; fq.y /= 1.06;
  vEdge = smoothstep(uFaceCos - 0.17, uFaceCos, dot(normalize(fq), uFaceDir));

  vec3 dir = normalize(n + vec3(0.0, -uDroop, 0.0) * uLayer);
  p += dir * uFurLen * uLayer * (1.0 - vEdge * 0.92);

  vN = normalize(normalMatrix * n);
  vec4 w = modelMatrix * vec4(p, 1.0);
  vW = w.xyz;
  gl_Position = projectionMatrix * viewMatrix * w;
}`;

const FUR_FRAG = LIGHT_GLSL + `
uniform float uLayer, uDensity; uniform vec3 uFur; uniform vec3 uTip;
uniform vec3 uFaceC, uFaceDir; uniform float uFaceCos;
varying vec3 vN; varying vec3 vRest; varying vec3 vW; varying float vEdge;

float h31(vec3 p){
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.x + p.y) * p.z);
}
void main(){
  vec3 fq = vRest - uFaceC; fq.y /= 1.06;
  float edge = smoothstep(uFaceCos - 0.17, uFaceCos, dot(normalize(fq), uFaceDir));
  if (edge > 0.97) discard;
  vec3 cell = floor(vRest * uDensity);
  float strand = h31(cell);
  if (uLayer > 0.0 && uLayer > 0.18 + strand * 0.94) discard;

  float root = mix(0.60, 0.98, uLayer);
  vec3 base = mix(uFur, uTip, uLayer * 0.75) * root;
  base *= 0.90 + h31(cell + 7.1) * 0.20;
  base *= mix(1.0, 0.52, edge);                        /* shadow inside the hood */

  vec3 N = normalize(vN);
  vec3 V = normalize(cameraPosition - vW);
  vec3 col = shadeIt(base, N, V, 0.09 + uLayer * 0.17);
  gl_FragColor = vec4(fogIt(col, length(cameraPosition - vW)), 1.0);
}`;

const FACE_FRAG = LIGHT_GLSL + `
uniform vec3 uSkin; uniform vec3 uBlush; uniform float uBlink; uniform float uSmile;
uniform vec3 uInk; uniform float uEyeSize, uEyeSpread, uEyeHeight, uMouthW, uMouthCurve, uBlushAmt;
varying vec3 vU; varying vec3 vN; varying vec3 vW;

float ring(vec2 p, vec2 c, float r, float w){
  return 1.0 - smoothstep(w * 0.55, w, abs(length(p - c) - r));
}
void main(){
  vec3 u = normalize(vU);
  vec2 f = u.xy;
  float front = smoothstep(0.10, 0.48, u.z);

  vec3 col = uSkin;
  col *= 1.0 - smoothstep(0.44, 1.02, length(f)) * 0.34;        /* hood shadow at the rim */
  col *= 1.0 + smoothstep(0.55, -0.2, f.y) * 0.05;

  /* blush */
  float bl = 0.0;
  bl += 1.0 - smoothstep(0.03, 0.27, length((f - vec2(-0.575 * uEyeSpread, -0.012 + uEyeHeight * 0.4)) * vec2(1.0, 1.42)));
  bl += 1.0 - smoothstep(0.03, 0.27, length((f - vec2( 0.575 * uEyeSpread, -0.012 + uEyeHeight * 0.4)) * vec2(1.0, 1.42)));
  col = mix(col, uBlush, clamp(bl, 0.0, 1.0) * 0.58 * uBlushAmt * front);

  /* eyes */
  float eh = max(0.10, 1.0 - uBlink);
  float ey = 0.0;
  ey += 1.0 - smoothstep(0.100, 0.122, length((f - vec2(-0.345 * uEyeSpread, 0.150 + uEyeHeight)) * vec2(1.0, 1.0 / eh)) / uEyeSize);
  ey += 1.0 - smoothstep(0.100, 0.122, length((f - vec2( 0.345 * uEyeSpread, 0.150 + uEyeHeight)) * vec2(1.0, 1.0 / eh)) / uEyeSize);
  ey = clamp(ey, 0.0, 1.0) * front;

  /* smile */
  float sm = ring(f, vec2(0.0, -0.012 + uSmile * 0.03 + uEyeHeight * 0.25), (0.165 + uSmile * 0.05) * uMouthW, 0.046);
  sm *= step(f.y, -0.046 + uEyeHeight * 0.25 + (1.0 - uMouthCurve) * 0.05) * front;

  float ink = clamp(ey + sm, 0.0, 1.0);

  vec3 N = normalize(vN);
  vec3 V = normalize(cameraPosition - vW);
  vec3 lit = shadeIt(col, N, V, 0.22);
  lit += uSkin * 0.10 * pow(max(dot(N, vec3(0.0,0.2,1.0)), 0.0), 2.0);   /* soft sss */
  lit = mix(lit, uInk, ink);
  /* tiny catchlight */
  float cl = (1.0 - smoothstep(0.024, 0.036, length(f - vec2(-0.308 * uEyeSpread, 0.198 + uEyeHeight))))
           + (1.0 - smoothstep(0.024, 0.036, length(f - vec2( 0.382 * uEyeSpread, 0.198 + uEyeHeight))));
  lit = mix(lit, vec3(1.0), clamp(cl, 0.0, 1.0) * ey * 0.85 * (1.0 - uBlink));

  gl_FragColor = vec4(fogIt(lit, length(cameraPosition - vW)), 1.0);
}`;

const SHELLS = 10, FUR_LEN = 0.058;
const faceGeo = new THREE.SphereGeometry(1, 40, 28);

function makeFuzzling(cfg){
  const R = cfg.rig;
  const geo = buildBody(R);
  const met = rigMetrics(R);
  const faceC = new THREE.Vector3().fromArray(met.faceC);
  const faceR = new THREE.Vector3().fromArray(met.faceR);
  const fur = new THREE.Color(cfg.fur);
  const tip = fur.clone().lerp(new THREE.Color(0xFFF6E4), 0.15);
  const skin = fur.clone().lerp(new THREE.Color(0xFDF2DE), 0.72);
  const blush = new THREE.Color(0xF0A8A4).lerp(fur, 0.14);

  const shared = {
    uPhase:     { value: 0 },
    uSwing:     { value: 0 },
    uFur:       { value: fur },
    uTip:       { value: tip },
    uFurLen:    { value: FUR_LEN * R.furLength },
    uDensity:   { value: 132.0 * R.furDensity },
    uDroop:     { value: 0.42 },
    uArmPivot:  { value: new THREE.Vector2().fromArray(met.armPivot) },
    uLegPivotY: { value: met.legPivotY },
    uFaceC:     { value: faceC },
    uFaceDir:   { value: FACE_DIR },
    uFaceCos:   { value: R.faceOpen }
  };

  const root = new THREE.Group();     // placed on the track
  const tilt = new THREE.Group();     // lean + bank
  const body = new THREE.Group();     // hop
  root.add(tilt); tilt.add(body);

  for (let i = 0; i < SHELLS; i++){
    const m = new THREE.ShaderMaterial({
      uniforms: Object.assign({}, LIGHTU, shared, { uLayer: { value: i / (SHELLS - 1) } }),
      vertexShader: FUR_VERT, fragmentShader: FUR_FRAG
    });
    const mesh = new THREE.Mesh(geo, m);
    mesh.renderOrder = 2 + i;
    mesh.frustumCulled = false;
    body.add(mesh);
  }

  const faceU = {
    uSkin:       { value: skin },
    uBlush:      { value: blush },
    uBlink:      { value: 0 },
    uSmile:      { value: 0 },
    uInk:        { value: new THREE.Color(R.eye) },
    uEyeSize:    { value: R.eyeSize },
    uEyeSpread:  { value: R.eyeSpread },
    uEyeHeight:  { value: R.eyeHeight },
    uMouthW:     { value: R.mouthWidth },
    uMouthCurve: { value: R.mouthCurve },
    uBlushAmt:   { value: R.blush }
  };
  const face = new THREE.Mesh(faceGeo, new THREE.ShaderMaterial({
    uniforms: Object.assign({}, LIGHTU, faceU),
    vertexShader: `varying vec3 vU; varying vec3 vN; varying vec3 vW;
      void main(){ vU = position; vN = normalize(normalMatrix * normal);
        vec4 w = modelMatrix * vec4(position,1.0); vW = w.xyz;
        gl_Position = projectionMatrix * viewMatrix * w; }`,
    fragmentShader: FACE_FRAG
  }));
  face.position.copy(faceC);
  face.scale.copy(faceR);
  face.renderOrder = 1;
  body.add(face);

  /* contact shadow */
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.82 * R.girth, 24),
    new THREE.MeshBasicMaterial({ map: BLOB_TEX, transparent: true, opacity: .42, depthWrite: false, color: 0x4C4030 })
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = 0.09;
  tilt.add(shadow);

  return { root, tilt, body, face, shared, faceU, shadow, color: fur, rig: R, metrics: met };
}

/* soft round blob-shadow texture ---------------------------------------- */
const BLOB_TEX = (() => {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(64, 64, 2, 64, 64, 62);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(.42, 'rgba(255,255,255,.62)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad; g.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c); t.needsUpdate = true; return t;
})();

/* ============================ 6. WORLD PROPS ============================= */
const propMat = (colA, colB, rim) => new THREE.ShaderMaterial({
  uniforms: Object.assign({}, LIGHTU, {
    uA: { value: new THREE.Color(colA) },
    uB: { value: new THREE.Color(colB) },
    uRim: { value: rim === undefined ? 0.18 : rim }
  }),
  vertexShader: `
    varying vec3 vN; varying vec3 vW; varying vec3 vL;
    void main(){
      vL = position;
      vec4 lp = vec4(position, 1.0);
      vec3 ln = normal;
      #ifdef USE_INSTANCING
        lp = instanceMatrix * lp;
        ln = mat3(instanceMatrix) * ln;
      #endif
      vN = normalize(normalMatrix * normalize(ln));
      vec4 w = modelMatrix * lp; vW = w.xyz;
      gl_Position = projectionMatrix * viewMatrix * w; }`,
  fragmentShader: LIGHT_GLSL + `
    uniform vec3 uA; uniform vec3 uB; uniform float uRim;
    varying vec3 vN; varying vec3 vW; varying vec3 vL;
    void main(){
      vec3 base = mix(uA, uB, clamp(vL.y * 0.5 + 0.5, 0.0, 1.0));
      float g = sin(vW.x * 0.63) * sin(vW.z * 0.71) * sin(vW.y * 0.44);
      base *= 0.955 + g * 0.075;
      vec3 col = shadeIt(base, normalize(vN), normalize(cameraPosition - vW), uRim);
      gl_FragColor = vec4(fogIt(col, length(cameraPosition - vW)), 1.0);
    }`
});

const world = new THREE.Group();
scene.add(world);

/* -- giant hood-capped mushrooms (they echo the fuzzlings' silhouette) -- */
{
  const capGeo = new THREE.SphereGeometry(1, 20, 14, 0, Math.PI * 2, 0, Math.PI * 0.56);
  const gillGeo = new THREE.CircleGeometry(1, 20); gillGeo.rotateX(Math.PI / 2);
  const stemProfile = [];
  for (let i = 0; i <= 10; i++){
    const t = i / 10;
    stemProfile.push(new THREE.Vector2(0.30 - Math.sin(t * 2.3) * 0.12 + t * 0.05, t));
  }
  const stemGeo = new THREE.LatheGeometry(stemProfile, 14);

  const palettes = __W.props.caps.palettes;
  const caps = palettes.map(p => propMat(p[0], p[1], 0.30));
  const stems = palettes.map(p => propMat(p[2], 0xE0CFB4, 0.22));
  const gillMat = propMat(0xE9D6BE, 0xC9AE90, 0.06);

  const capI  = palettes.map(() => []);
  const stemI = palettes.map(() => []);
  const gillI = [];
  const blobs = [];

  let tries = 0;
  const placed = [];
  while (placed.length < __W.props.caps.count && tries < __W.props.caps.count * 40){
    tries++;
    const x = (rnd() - .5) * 400, z = (rnd() - .5) * 400;
    const near = distToTrack(x, z);
    if (near.d < ROAD_HALF + 4.2 || near.d > 120) continue;
    let ok = true;
    for (const p of placed) if ((p[0] - x) ** 2 + (p[1] - z) ** 2 < 130) { ok = false; break; }
    if (!ok) continue;
    placed.push([x, z]);

    const y = terrainHeight(x, z);
    const s = 1.1 + Math.pow(rnd(), 1.8) * 5.4;
    const pi = (rnd() * palettes.length) | 0;
    const rot = rnd() * Math.PI * 2;
    const lean = (rnd() - .5) * 0.16;

    const stemH = s * (1.5 + rnd() * 1.1);
    const mS = new THREE.Matrix4().makeTranslation(x, y - 0.1, z)
      .multiply(new THREE.Matrix4().makeRotationZ(lean))
      .multiply(new THREE.Matrix4().makeRotationY(rot))
      .multiply(new THREE.Matrix4().makeScale(s * .74, stemH, s * .74));
    stemI[pi].push(mS);

    const capR = s * (1.25 + rnd() * .55);
    const capY = y - 0.1 + stemH * .96;
    const mC = new THREE.Matrix4().makeTranslation(x + Math.sin(lean) * stemH * .5, capY, z)
      .multiply(new THREE.Matrix4().makeRotationZ(lean))
      .multiply(new THREE.Matrix4().makeRotationY(rot))
      .multiply(new THREE.Matrix4().makeScale(capR, capR * (.78 + rnd() * .4), capR));
    capI[pi].push(mC);
    gillI.push(new THREE.Matrix4().makeTranslation(x + Math.sin(lean) * stemH * .5, capY - 0.01, z)
      .multiply(new THREE.Matrix4().makeScale(capR * .99, 1, capR * .99)));
    blobs.push([x, y + .04, z, capR * 1.15]);
  }

  const push = (geo, mat, mats) => {
    if (!mats.length) return;
    const im = new THREE.InstancedMesh(geo, mat, mats.length);
    mats.forEach((m, i) => im.setMatrixAt(i, m));
    im.instanceMatrix.needsUpdate = true;
    im.frustumCulled = false;
    world.add(im);
  };
  palettes.forEach((_, i) => { push(capGeo, caps[i], capI[i]); push(stemGeo, stems[i], stemI[i]); });
  push(gillGeo, gillMat, gillI);

  /* blob shadows under the mushrooms */
  const bGeo = new THREE.CircleGeometry(1, 14); bGeo.rotateX(-Math.PI / 2);
  const bMat = new THREE.MeshBasicMaterial({ map: BLOB_TEX, transparent: true, opacity: .30, depthWrite: false, color: 0x4C4030 });
  const bIm = new THREE.InstancedMesh(bGeo, bMat, blobs.length);
  blobs.forEach((b, i) => bIm.setMatrixAt(i, new THREE.Matrix4().makeTranslation(b[0], b[1], b[2])
    .multiply(new THREE.Matrix4().makeScale(b[3], 1, b[3]))));
  bIm.instanceMatrix.needsUpdate = true;
  bIm.frustumCulled = false;
  world.add(bIm);
}

/* ------------------------ fuzz tufts (ground cover) --------------------- */
{
  const tuft = new THREE.SphereGeometry(1, 8, 6);
  tuft.scale(1, 1.55, 1);
  const mats = __W.props.tufts.palettes.map(p => propMat(p[0], p[1], 0.27));
  const buckets = mats.map(() => []);
  for (let i = 0; i < __W.props.tufts.count; i++){
    const x = (rnd() - .5) * 380, z = (rnd() - .5) * 380;
    const near = distToTrack(x, z);
    if (near.d < ROAD_HALF + 0.9 || near.d > 115) continue;
    const y = terrainHeight(x, z);
    const s = .28 + rnd() * .62 + (near.d < ROAD_HALF + 4 ? .25 : 0);
    buckets[(rnd() * mats.length) | 0].push(new THREE.Matrix4()
      .makeTranslation(x, y + s * .5, z)
      .multiply(new THREE.Matrix4().makeRotationY(rnd() * 6.28))
      .multiply(new THREE.Matrix4().makeRotationZ((rnd() - .5) * .5))
      .multiply(new THREE.Matrix4().makeScale(s, s * (.8 + rnd() * .8), s)));
  }
  buckets.forEach((b, i) => {
    if (!b.length) return;
    const im = new THREE.InstancedMesh(tuft, mats[i], b.length);
    b.forEach((m, k) => im.setMatrixAt(k, m));
    im.instanceMatrix.needsUpdate = true;
    im.frustumCulled = false;
    world.add(im);
  });
}

/* --------------------------- trackside lanterns ------------------------- */
const lanternGlows = [];
{
  const postGeo = new THREE.CylinderGeometry(0.085, 0.14, 1.85, 8);
  const bulbGeo = new THREE.SphereGeometry(0.30, 14, 10);
  const postMat = propMat(__W.props.lanterns.post, 0x7A6547, 0.14);
  const bulbMat = new THREE.MeshBasicMaterial({ color: __W.props.lanterns.bulb });
  const glowMat = new THREE.SpriteMaterial({ map: PUFF, color: __W.props.lanterns.glow, transparent: true,
    opacity: .55, depthWrite: false, blending: THREE.AdditiveBlending });

  const step = __W.props.lanterns.spacing, count = Math.floor(TOTAL / step);
  const posts = [], bulbs = [];
  const f = mkFrame();
  for (let i = 0; i < count; i++){
    frameAt(i * step, f);
    for (const s of [-1, 1]){
      const x = f.pos.x + f.right.x * (ROAD_HALF + 1.5) * s;
      const z = f.pos.z + f.right.z * (ROAD_HALF + 1.5) * s;
      const y = f.pos.y - 0.25;
      posts.push(new THREE.Matrix4().makeTranslation(x, y + .92, z));
      bulbs.push([x, y + 1.95, z]);
    }
  }
  const pim = new THREE.InstancedMesh(postGeo, postMat, posts.length);
  posts.forEach((m, i) => pim.setMatrixAt(i, m));
  pim.instanceMatrix.needsUpdate = true; pim.frustumCulled = false;
  world.add(pim);

  const bim = new THREE.InstancedMesh(bulbGeo, bulbMat, bulbs.length);
  bulbs.forEach((b, i) => bim.setMatrixAt(i, new THREE.Matrix4().makeTranslation(b[0], b[1], b[2])));
  bim.instanceMatrix.needsUpdate = true; bim.frustumCulled = false;
  world.add(bim);

  for (let i = 0; i < bulbs.length; i += 1){
    const sp = new THREE.Sprite(glowMat.clone());
    sp.position.set(bulbs[i][0], bulbs[i][1], bulbs[i][2]);
    sp.scale.setScalar(2.6);
    world.add(sp);
    lanternGlows.push({ sp, ph: rnd() * 6.28 });
  }
}

/* ------------------------------ start gate ------------------------------ */
{
  const g = new THREE.Group();
  const f = mkFrame(); frameAt(0, f);
  const postMat = propMat(__W.props.gate.post, 0xC2A271, 0.24);
  const bunting = propMat(__W.props.gate.banner, 0xD98878, 0.30);

  for (const s of [-1, 1]){
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.62, 7.4, 12), postMat);
    post.position.set(f.pos.x + f.right.x * (ROAD_HALF + 1.1) * s, f.pos.y + 3.5, f.pos.z + f.right.z * (ROAD_HALF + 1.1) * s);
    g.add(post);
    const knob = new THREE.Mesh(new THREE.SphereGeometry(0.72, 16, 12), bunting);
    knob.position.set(post.position.x, f.pos.y + 7.5, post.position.z);
    g.add(knob);
  }
  /* sagging banner between the posts */
  const W = (ROAD_HALF + 1.1) * 2, SEGS = 26;
  const bv = [], bi = [], bn = [];
  for (let i = 0; i <= SEGS; i++){
    const t = i / SEGS, s = t * 2 - 1;
    const sag = Math.cos(s * Math.PI * 0.5);
    const bx = f.pos.x + f.right.x * s * (W / 2), bz = f.pos.z + f.right.z * s * (W / 2);
    bv.push(bx, f.pos.y + 7.15 - sag * 0.55, bz);
    bv.push(bx, f.pos.y + 5.55 - sag * 0.75, bz);
    bn.push(0, 0, 1, 0, 0, 1);
  }
  for (let i = 0; i < SEGS; i++){
    const a = i * 2; bi.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
  }
  const bg = new THREE.BufferGeometry();
  bg.setAttribute('position', new THREE.Float32BufferAttribute(bv, 3));
  bg.setAttribute('normal', new THREE.Float32BufferAttribute(bn, 3));
  bg.setIndex(bi);
  bg.computeVertexNormals();
  const banner = new THREE.Mesh(bg, new THREE.MeshBasicMaterial({ color: __W.props.gate.banner, side: THREE.DoubleSide }));
  g.add(banner);

  /* little pennants */
  for (let i = 0; i < 16; i++){
    const t = (i + .5) / 16, s = t * 2 - 1;
    const sag = Math.cos(s * Math.PI * 0.5);
    const pen = new THREE.Mesh(new THREE.ConeGeometry(0.30, 0.78, 4),
      new THREE.MeshBasicMaterial({ color: __W.props.gate.pennants[i % __W.props.gate.pennants.length] }));
    pen.position.set(f.pos.x + f.right.x * s * (W / 2), f.pos.y + 5.1 - sag * .78, f.pos.z + f.right.z * s * (W / 2));
    pen.rotation.x = Math.PI;
    g.add(pen);
  }
  world.add(g);
}

/* ---------------------------- floating islets --------------------------- */
const islets = [];
{
  const rockMat = propMat(0xC3A882, 0x8E7657, 0.16);
  const grassMat = propMat(0xA9C78E, 0x89AE6E, 0.22);
  for (let i = 0; i < __W.props.islets.count; i++){
    const g = new THREE.Group();
    const s = 6 + rnd() * 11;
    const rock = new THREE.Mesh(new THREE.ConeGeometry(1, 1.9, 9), rockMat);
    rock.scale.set(s, s * (.6 + rnd() * .5), s * (.8 + rnd() * .4));
    rock.rotation.x = Math.PI;
    rock.position.y = -s * .55;
    g.add(rock);
    const top = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 10, 0, 6.29, 0, Math.PI * .5), grassMat);
    top.scale.set(s * 1.02, s * .32, s * .82);
    g.add(top);
    for (let k = 0; k < 3; k++){
      const cap = new THREE.Mesh(new THREE.SphereGeometry(1, 12, 8, 0, 6.29, 0, Math.PI * .56),
        propMat(__W.props.islets.caps[k % __W.props.islets.caps.length], 0xB88A78, .3));
      const rr = s * (.12 + rnd() * .2);
      cap.scale.setScalar(rr);
      cap.position.set((rnd() - .5) * s, s * .28 + rr * .4, (rnd() - .5) * s * .7);
      g.add(cap);
    }
    const ang = rnd() * 6.28, rad = 120 + rnd() * 160;
    g.position.set(Math.cos(ang) * rad, 46 + rnd() * 52, Math.sin(ang) * rad);
    world.add(g);
    islets.push({ g, y0: g.position.y, ph: rnd() * 6.28, sp: .2 + rnd() * .3 });
  }
}

/* ------------------------------ drifting spores ------------------------- */
const spores = (() => {
  const N = __W.props.spores.count;
  const pos = new Float32Array(N * 3), col = new Float32Array(N * 3), sz = new Float32Array(N);
  const base = new THREE.Color();
  for (let i = 0; i < N; i++){
    pos[i*3]   = (rnd() - .5) * 300;
    pos[i*3+1] = rnd() * 44;
    pos[i*3+2] = (rnd() - .5) * 300;
    base.setHSL(__W.props.spores.hue + rnd() * __W.props.spores.hueSpread, __W.props.spores.sat, .78 + rnd() * .16);
    col[i*3] = base.r; col[i*3+1] = base.g; col[i*3+2] = base.b;
    sz[i] = .22 + rnd() * .55;
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  g.setAttribute('aSize', new THREE.BufferAttribute(sz, 1));
  const m = new THREE.ShaderMaterial({
    uniforms: { uTex: { value: PUFF }, uTime: { value: 0 } },
    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: `
      attribute float aSize; varying vec3 vC; varying float vF; uniform float uTime;
      void main(){
        vC = color;
        vec3 p = position;
        p.x += sin(uTime * 0.28 + p.z * 0.09) * 2.4;
        p.y += sin(uTime * 0.42 + p.x * 0.07) * 1.5;
        vec4 mv = modelViewMatrix * vec4(p, 1.0);
        float d = -mv.z;
        vF = clamp(1.0 - d / 230.0, 0.0, 1.0);
        gl_PointSize = aSize * 220.0 / max(d, 1.0);
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: `
      uniform sampler2D uTex; varying vec3 vC; varying float vF;
      void main(){
        vec4 t = texture2D(uTex, gl_PointCoord);
        gl_FragColor = vec4(vC, t.a * 0.55 * vF);
      }`,
    vertexColors: true
  });
  const pts = new THREE.Points(g, m);
  pts.frustumCulled = false;
  scene.add(pts);
  return { pts, m };
})();

/* ======================= 7. RACERS + SIMULATION ========================= */
const racers = RACERS.map((cfg, i) => {
  const fz = makeFuzzling(cfg);
  scene.add(fz.root);
  return {
    cfg, fz, idx: i,
    lane: LANES[cfg.lane],
    dist: -i * 1.35,
    vel: 0,
    phase: rnd() * 6.28,
    hop: 0,
    lean: 0, bank: 0,
    blink: 0, blinkT: 1 + rnd() * 4, lunge: 0,
    finished: false, finishTime: 0, place: 0,
    /* AI personality */
    base: 0, surgeA: 0, surgeF: 0, surgePh: rnd() * 6.28,
    stumbleT: 4 + rnd() * 8, stumble: 0,
    smile: 0,
    sway: rnd() * 6.28
  };
});
const you = racers[0];

/* ================================ INPUT ================================= */
let lastTap = 0, cadence = 0.22, tapCount = 0, streak = 0, streakWas = 0;
let locks = 0, lockFlash = 0, beatT = 0, beatPulse = 0;
const LOCK_EVERY = 8;
const nowSec = () => performance.now() / 1000;

function stride(){
  if (state !== 'race' || you.finished) return;
  const now = nowSec();
  const dt = lastTap ? now - lastTap : 999;
  lastTap = now;
  tapCount++;

  let quality, kind;
  if (dt < T.mash){
    quality = 0.12; kind = 'stumble';
    you.vel *= 0.86;
    streak = 0;
  } else if (dt < T.lo){
    quality = lerp(0.45, 1.0, (dt - T.mash) / (T.lo - T.mash)); kind = 'fast';
    streak = 0;
  } else if (dt <= T.hi){
    const half = Math.max(T.hi - T.ideal, T.ideal - T.lo);
    const off  = Math.abs(dt - T.ideal) / half;
    quality = lerp(1.28, 1.14, off); kind = 'good';
    streak++;
  } else if (dt < T.cold){
    quality = lerp(1.0, 0.70, (dt - T.hi) / (T.cold - T.hi)); kind = 'slow';
    streak = 0;
  } else {
    quality = 0.92; kind = 'reset';
    streak = 0;
  }

  if (dt < 5) cadence = smoothDamp(cadence, dt, 9, 0.12);

  const bonus = 1 + Math.min(streak, 12) * 0.022;
  /* scaled by timeScale so a stride is worth the same in world terms whether
     or not the finish rig has dropped everything into slow motion */
  you.vel = Math.min(MAXSPEED, you.vel + T.imp * quality * bonus * timeScale);
  you.phase += Math.PI;                       // snap the legs onto the beat
  you.hop = Math.max(you.hop, 0.10 + quality * 0.10);
  beatT = 0;                                  // metronome re-phases to your tap

  audio.step(quality, dt);

  if (kind === 'good'){
    /* eight clean strides = a lock. Tetris clears lines; you clear ground. */
    if (streak > 0 && streak % LOCK_EVERY === 0){
      locks++;
      you.vel = Math.min(MAXSPEED, you.vel + 1.7);
      lockFlash = 1;
      if (locks <= 3 || locks % 5 === 0)
        callout(locks === 1 ? 'LOCKED IN' : 'LOCK \u00D7' + locks, T.col);
      audio.lock(locks);
    } else if (streak % 3 === 0){
      audio.ping(Math.min(streak, 28));
    }
  } else if (kind === 'stumble' && tapCount % 3 === 0){
    callout('TOO FAST', '#D97A5E');
  } else if (kind === 'slow' && streakWas >= LOCK_EVERY){
    callout('DROPPED', '#B08A6A');
  }
  streakWas = streak;
  if (tapCount === 5) hideHint();
}

addEventListener('keydown', e => {
  if (e.code === 'Space' || e.key === ' '){
    e.preventDefault();
    if (e.repeat) return;
    if (state === 'title') startRace();
    else if (state === 'finish'){ if (clock > restartAt) reset(); }
    else stride();
  }
  if (e.key === 'm' || e.key === 'M') toggleMute();
});
canvas.addEventListener('pointerdown', e => {
  if (state === 'title') startRace(); else stride();
});
addEventListener('touchstart', e => { if (e.target === canvas) e.preventDefault(); }, { passive: false });

/* ================================ AUDIO ================================= */
const audio = (() => {
  let ctx = null, master = null, muted = false, wind = null, duckLP = null, heart = null;
  let started = false;
  function ensure(){
    if (ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    ctx = new AC();
    master = ctx.createGain();
    master.gain.value = muted ? 0 : 0.55;
    /* everything runs through one lowpass so the world can audibly close down
       when the finish rig drops into slow motion */
    duckLP = ctx.createBiquadFilter();
    duckLP.type = 'lowpass'; duckLP.frequency.value = 20000; duckLP.Q.value = 0.4;
    master.connect(duckLP).connect(ctx.destination);

    /* ambient breeze */
    const buf = ctx.createBuffer(1, ctx.sampleRate * 3, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * 0.5;
    const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 320;
    const g = ctx.createGain(); g.gain.value = 0.035;
    src.connect(lp).connect(g).connect(master); src.start();
    wind = g;
  }
  function env(node, a, d, peak){
    const t = ctx.currentTime;
    node.gain.setValueAtTime(0.0001, t);
    node.gain.exponentialRampToValueAtTime(peak, t + a);
    node.gain.exponentialRampToValueAtTime(0.0001, t + a + d);
  }
  return {
    resume(){ ensure(); started = true; if (ctx && ctx.state === 'suspended') ctx.resume(); },

    /* The ambient bed is a looping buffer and the heartbeat is a timer: neither
       cares that requestAnimationFrame stops when the page is hidden, so
       backgrounding the tab used to leave the Hollow droning away behind you.
       Park the whole context instead. */
    setParked(park){
      if (!ctx) return;
      if (park){
        if (heart){ clearInterval(heart); heart = null; }
        if (ctx.state === 'running') ctx.suspend();
      } else if (started && !muted && ctx.state === 'suspended'){
        ctx.resume();
      }
    },
    setMuted(m){ muted = m; if (master) master.gain.value = m ? 0 : 0.55; },
    step(q, dt){
      ensure(); if (!ctx || muted) return;
      const t = ctx.currentTime;
      /* soft paw thump */
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine';
      o.frequency.setValueAtTime(190 + q * 60, t);
      o.frequency.exponentialRampToValueAtTime(62, t + .10);
      env(g, .004, .11, .22 * clamp(q, .2, 1.4));
      o.connect(g).connect(master); o.start(t); o.stop(t + .18);
      /* fluff rustle */
      const b = ctx.createBuffer(1, 1800, ctx.sampleRate), dd = b.getChannelData(0);
      for (let i = 0; i < dd.length; i++) dd[i] = (Math.random() * 2 - 1) * (1 - i / dd.length) ** 2;
      const s = ctx.createBufferSource(); s.buffer = b;
      const bp = ctx.createBiquadFilter(); bp.type = 'bandpass';
      bp.frequency.value = 1500 + q * 900; bp.Q.value = 0.9;
      const g2 = ctx.createGain(); g2.gain.value = .11 * q;
      s.connect(bp).connect(g2).connect(master); s.start(t);
    },
    ping(n){
      ensure(); if (!ctx || muted) return;
      const t = ctx.currentTime;
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'triangle';
      const scale = [0, 2, 4, 7, 9, 12, 14, 16];
      o.frequency.value = 523.25 * Math.pow(2, scale[Math.min(n / 4 | 0, 7)] / 12);
      env(g, .006, .30, .10);
      o.connect(g).connect(master); o.start(t); o.stop(t + .4);
    },
    beep(hi){
      ensure(); if (!ctx || muted) return;
      const t = ctx.currentTime;
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine'; o.frequency.value = hi ? 880 : 440;
      env(g, .008, hi ? .55 : .22, .20);
      o.connect(g).connect(master); o.start(t); o.stop(t + .7);
    },
    fanfare(win){
      ensure(); if (!ctx || muted) return;
      const notes = win ? [523, 659, 784, 1046, 1318] : [523, 587, 659, 698];
      notes.forEach((f, i) => {
        const t = ctx.currentTime + i * .13;
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'triangle'; o.frequency.value = f;
        g.gain.setValueAtTime(.0001, t);
        g.gain.exponentialRampToValueAtTime(.16, t + .02);
        g.gain.exponentialRampToValueAtTime(.0001, t + .55);
        o.connect(g).connect(master); o.start(t); o.stop(t + .6);
      });
    },
    tick(){
      ensure(); if (!ctx || muted) return;
      const t = ctx.currentTime;
      const o = ctx.createOscillator(), g = ctx.createGain(), hp = ctx.createBiquadFilter();
      hp.type = 'highpass'; hp.frequency.value = 900;
      o.type = 'square'; o.frequency.value = 1760;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.030, t + 0.002);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.040);
      o.connect(hp).connect(g).connect(master); o.start(t); o.stop(t + .06);
    },
    lock(n){
      ensure(); if (!ctx || muted) return;
      const t = ctx.currentTime;
      [0, 4, 7].forEach((semi, i) => {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'triangle';
        o.frequency.value = 659.25 * Math.pow(2, (semi + Math.min(n, 6)) / 12);
        const s = t + i * 0.035;
        g.gain.setValueAtTime(.0001, s);
        g.gain.exponentialRampToValueAtTime(.13, s + .01);
        g.gain.exponentialRampToValueAtTime(.0001, s + .42);
        o.connect(g).connect(master); o.start(s); o.stop(s + .45);
      });
    },
    tempoUp(n){
      ensure(); if (!ctx || muted) return;
      /* a rising figure that transposes up a whole tone per level */
      const root = 392 * Math.pow(2, (n - 1) * 2 / 12);
      [0, 5, 9, 12, 17].forEach((semi, i) => {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = i > 2 ? 'triangle' : 'square';
        o.frequency.value = root * Math.pow(2, semi / 12);
        const s = ctx.currentTime + i * 0.085;
        g.gain.setValueAtTime(.0001, s);
        g.gain.exponentialRampToValueAtTime(i > 2 ? .17 : .10, s + .012);
        g.gain.exponentialRampToValueAtTime(.0001, s + .60);
        o.connect(g).connect(master); o.start(s); o.stop(s + .65);
      });
      /* a low swell underneath so the level change lands in the chest */
      const o = ctx.createOscillator(), g = ctx.createGain(), t = ctx.currentTime;
      o.type = 'sine'; o.frequency.setValueAtTime(70, t);
      o.frequency.exponentialRampToValueAtTime(140, t + .5);
      g.gain.setValueAtTime(.0001, t);
      g.gain.exponentialRampToValueAtTime(.20, t + .05);
      g.gain.exponentialRampToValueAtTime(.0001, t + .8);
      o.connect(g).connect(master); o.start(t); o.stop(t + .85);
    },
    duck(on, level){
      ensure(); if (!ctx || !duckLP) return;
      const t = ctx.currentTime;
      const f = on ? [1500, 900, 560][clamp(level, 0, 2)] : 20000;
      duckLP.frequency.cancelScheduledValues(t);
      duckLP.frequency.setValueAtTime(Math.max(120, duckLP.frequency.value), t);
      duckLP.frequency.exponentialRampToValueAtTime(f, t + (on ? 0.55 : 0.75));
      if (on && level >= 1 && !heart) heart = setInterval(() => this.thump(), 620);
      if (!on && heart){ clearInterval(heart); heart = null; }
    },
    thump(){
      ensure(); if (!ctx || muted) return;
      const t = ctx.currentTime;
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine';
      o.frequency.setValueAtTime(64, t);
      o.frequency.exponentialRampToValueAtTime(38, t + .22);
      g.gain.setValueAtTime(.0001, t);
      g.gain.exponentialRampToValueAtTime(.34, t + .02);
      g.gain.exponentialRampToValueAtTime(.0001, t + .30);
      o.connect(g).connect(master); o.start(t); o.stop(t + .34);
    },
    shutter(){
      ensure(); if (!ctx || muted) return;
      const t = ctx.currentTime;
      /* two mechanical clacks: curtain open, curtain shut */
      [0, 0.055].forEach((off, k) => {
        const b = ctx.createBuffer(1, 900, ctx.sampleRate), d = b.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / d.length, 7);
        const src = ctx.createBufferSource(); src.buffer = b;
        const bp = ctx.createBiquadFilter();
        bp.type = 'bandpass'; bp.frequency.value = k ? 2600 : 4200; bp.Q.value = 1.4;
        const g = ctx.createGain(); g.gain.value = k ? .30 : .38;
        src.connect(bp).connect(g).connect(ctx.destination);   // bypass the duck
        src.start(t + off);
      });
      /* a bright ring so the freeze lands */
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = 'sine'; o.frequency.value = 2093;
      g.gain.setValueAtTime(.0001, t);
      g.gain.exponentialRampToValueAtTime(.09, t + .006);
      g.gain.exponentialRampToValueAtTime(.0001, t + 1.1);
      o.connect(g).connect(ctx.destination); o.start(t); o.stop(t + 1.2);
    },
    setWind(v){ if (wind) wind.gain.value = 0.030 + v * 0.055; }
  };
})();

/* hidden tab, minimised window, or navigating away: silence everything */
document.addEventListener('visibilitychange', () => audio.setParked(document.hidden));
addEventListener('pagehide', () => audio.setParked(true));
addEventListener('pageshow', () => audio.setParked(false));
addEventListener('blur', () => { if (document.hidden) audio.setParked(true); });

let muted = false;
function toggleMute(){
  muted = !muted; audio.setMuted(muted);
  document.getElementById('mute').textContent = muted ? 'MUTED' : 'SOUND';
}
document.getElementById('mute').onclick = toggleMute;

/* ============================== HUD PLUMBING ============================ */
const el = id => document.getElementById(id);
const railEl = el('rail'), boardRows = el('boardrows');
const pips = [];
{
  for (let i = 1; i < LAPS; i++){
    const t = document.createElement('div');
    t.className = 'tick'; t.style.left = (i / LAPS * 100) + '%';
    railEl.appendChild(t);
  }
  racers.forEach(r => {
    const d = document.createElement('div');
    d.className = 'pip' + (r.cfg.you ? ' me' : '');
    d.style.background = '#' + r.cfg.fur.toString(16).padStart(6, '0');
    railEl.appendChild(d);
    pips.push(d);
  });
  racers.forEach(r => {
    const row = document.createElement('div');
    row.className = 'row' + (r.cfg.you ? ' me' : '');
    row.innerHTML = `<span class="pos"></span><span class="dot" style="background:#${r.cfg.fur.toString(16).padStart(6,'0')}"></span><span class="nm">${r.cfg.name}</span><span class="gap"></span>`;
    boardRows.appendChild(row);
    r.row = row;
  });
  applyTempo(true);
}

/* Slide and narrow the band, recolour everything that keys off the tempo.
   This is the one piece of UI that has to sell the Tetris idea: the player
   should SEE the landing zone shrink the instant a lap ticks over.          */
function applyTempo(instant){
  const zone = el('zone');
  if (instant) zone.style.transition = 'none';
  zone.style.left  = (T.lo / DIAL_MAX * 100) + '%';
  zone.style.width = ((T.hi - T.lo) / DIAL_MAX * 100) + '%';
  zone.style.background =
    `linear-gradient(90deg, ${T.col}44, ${T.col}CC, ${T.col}44)`;
  el('beat').style.left = (T.ideal / DIAL_MAX * 100) + '%';
  if (instant){ void zone.offsetWidth; zone.style.transition = ''; }

  el('tempov').innerHTML = T.n + `<small>${T.name}</small>`;
  el('tempochip').style.boxShadow = `0 0 0 2px ${T.col}66, var(--shadow)`;
  document.documentElement.style.setProperty('--tempo-col', T.col);
  document.documentElement.style.setProperty('--tint', T.tint);
}

function onTempoUp(){
  applyTempo(false);
  gradeFog.set(T.fog); gradeLight.set(T.light); gradeSky.set(T.sky);
  tempoJolt = 1; tempoBannerT = 2.4;
  el('tnum').textContent  = 'TEMPO ' + T.n;
  el('tname').textContent = T.name;
  el('tdesc').textContent = T.tag;
  const b = el('tempoup');
  b.style.animation = 'none'; void b.offsetWidth;
  b.style.animation = 'tempoup 2.4s cubic-bezier(.2,.8,.3,1) forwards';
  audio.tempoUp(T.n);
}
/* phones get told to tap the screen, not a key they do not have */
if (matchMedia('(hover: none)').matches || 'ontouchstart' in window){
  el('hint').innerHTML = 'tap the screen when the needle is inside the band';
  document.querySelectorAll('.tapkey').forEach(n => { n.textContent = 'TAP'; });
}

function hideHint(){
  const h = el('hint');
  h.style.transition = 'opacity .6s'; h.style.opacity = '0';
}
let calloutT = 0;
function callout(txt, color){
  if (tempoBannerT > 0.9) return;        // the level-up banner owns the screen
  const c = el('callout');
  c.textContent = txt;
  c.style.color = color;
  c.style.animation = 'none';
  void c.offsetWidth;
  c.style.animation = 'popup 1.25s ease-out forwards';
}
function bigText(txt, dur){
  const b = el('big');
  b.textContent = txt;
  b.style.animation = 'none';
  void b.offsetWidth;
  b.style.animation = `count ${dur}s ease-out forwards`;
}

/* ============================ GAME STATE FLOW =========================== */
let state = 'title';
let clock = 0, raceTime = 0, countdown = 0, finishHold = 0, celebrate = 0, bestStreak = 0;
let restartAt = 0, sporeRate = 1, sporeTime = 0, tempoJolt = 0, tempoBannerT = 0;

/* ------------------------------------------------------------ PHOTO FINISH --
   The last 38 metres run on a separate clock. The world drops into slow motion,
   the camera cuts to a trackside rig level with the tape, and the instant you
   cross we freeze the frame into an actual photograph — shutter, flash, and a
   reference line projected from the real finish line in world space, so the
   picture genuinely shows who was in front.                                   */
const PHOTO_ARM = 32;
const photo = { phase: 'off', t: 0, rival: null, gap: 0, close: 0, blend: 0,
                margin: 0, tag: '', snapped: false };
let timeScale = 1, scaleTarget = 1;
const gradeFog   = new THREE.Color(TEMPI[0].fog);
const gradeLight = new THREE.Color(TEMPI[0].light);
const gradeSky   = new THREE.Color(TEMPI[0].sky);

el('startbtn').onclick = startRace;
el('againbtn').onclick = reset;

function startRace(){
  audio.resume();
  el('title').classList.add('hide');
  el('finish').classList.add('hide');
  state = 'countdown';
  countdown = 3.9;
  countShown = 4;
  raceTime = 0; finishHold = 0; celebrate = 0;
  lastTap = 0; tapCount = 0; streak = 0; streakWas = 0; bestStreak = 0; cadence = .22;
  locks = 0; lockFlash = 0; beatT = 0; beatPulse = 0;
  TEMPO = 0; T = TEMPI[0];
  gradeFog.set(T.fog); gradeLight.set(T.light); gradeSky.set(T.sky);
  LIGHTU.uFogCol.value.set(T.fog);
  LIGHTU.uLightCol.value.set(T.light);
  sky.material.uniforms.uGrade.value.set(T.sky);
  scene.fog.color.set(T.fog);
  sporeRate = 1; tempoJolt = 0; tempoBannerT = 0;
  resetPhoto();
  racers.forEach(r => { r.lunge = 0; r.fz.body.scale.set(1, 1, 1); });
  applyTempo(true);
  el('tempoup').style.animation = 'none';
}
let countShown = 4;

function reset(){
  racers.forEach((r, i) => {
    r.dist = -i * 1.35; r.vel = 0; r.finished = false; r.finishTime = 0; r.place = 0;
    r.hop = 0; r.stumble = 0; r.smile = 0;
  });
  assignPersonalities();
  el('hint').style.opacity = '1';
  startRace();
}

function assignPersonalities(){
  /* CPU archetypes: sprinter fades, metronome, closer, wobbler, rival */
  const specs = [
    null,
    { base: 25.6, surgeA: 1.3, surgeF: .30, fade:  2.4 },   // Pip — fast starter
    { base: 24.0, surgeA: 0.5, surgeF: .12, fade:  0.0 },   // Bibo — metronome
    { base: 23.4, surgeA: 2.1, surgeF: .21, fade: -2.6 },   // Tova — closer
    { base: 24.6, surgeA: 2.6, surgeF: .46, fade:  0.4 },   // Nim  — wobbler
    { base: 26.4, surgeA: 1.1, surgeF: .17, fade: -0.8 }    // Wuff — the rival
  ];
  racers.forEach((r, i) => {
    if (!specs[i]) return;
    const s = specs[i];
    r.base = s.base + (rnd() - .5) * .8;
    r.surgeA = s.surgeA; r.surgeF = s.surgeF; r.fade = s.fade;
    r.surgePh = rnd() * 6.28;
    r.stumbleT = 5 + rnd() * 9;
  });
}
assignPersonalities();

/* ========================= THE FINISH LINE RIG ========================== */
const LINE = mkFrame();
frameAt(0, LINE);

/* --- the tape. Two halves hinged on the posts; the winner breaks it. ------ */
const tape = new THREE.Group();
const tapeHalves = [];
{
  tape.position.copy(LINE.pos); tape.position.y += 1.16;
  tape.rotation.y = Math.atan2(LINE.tan.x, LINE.tan.z);
  const mat = new THREE.MeshBasicMaterial({ color: 0xFFF6E2, side: THREE.DoubleSide });
  for (const side of [-1, 1]){
    const pivot = new THREE.Object3D();
    pivot.position.x = side * ROAD_HALF;
    const m = new THREE.Mesh(new THREE.BoxGeometry(ROAD_HALF, 0.075, 0.02), mat);
    m.position.x = -side * ROAD_HALF / 2;
    pivot.add(m);
    tape.add(pivot);
    tapeHalves.push({ pivot, side, vy: 0, spin: 0 });
  }
  tape.visible = false;
  tape.scale.y = 1;
  scene.add(tape);
}
let tapeBroken = false, tapeFade = 0;

function updateTape(dt){
  const want = (photo.phase === 'approach' || photo.phase === 'snap') && !tapeBroken ? 1 : 0;
  tapeFade = smoothDamp(tapeFade, want, 6, dt);
  tape.visible = tapeFade > 0.02 || tapeBroken;
  tape.scale.set(1, tapeBroken ? 1 : tapeFade, 1);
  if (tapeBroken){
    tape.visible = true;
    for (const h of tapeHalves){
      h.vy -= 9.0 * dt;
      h.spin += dt * h.side * 2.4;
      h.pivot.rotation.y = h.spin;
      h.pivot.rotation.z = h.side * Math.min(1.3, Math.abs(h.spin) * 0.9);
      h.pivot.position.y += h.vy * dt;
      if (h.pivot.position.y < -1.4) h.pivot.visible = false;
    }
  }
}
function breakTape(){
  if (tapeBroken) return;
  tapeBroken = true;
  for (const h of tapeHalves){ h.vy = 1.4; h.pivot.visible = true; }
}

/* --- you-are-here ring, so the print is readable at a glance -------------- */
const youRing = new THREE.Group();
const youMark = new THREE.Mesh(
  new THREE.ConeGeometry(0.26, 0.46, 4),
  new THREE.MeshBasicMaterial({ color: 0xFFF2D6, transparent: true, opacity: 0, depthWrite: false })
);
youMark.rotation.x = Math.PI;                       // point down at the player
const youGlow = new THREE.Sprite(new THREE.SpriteMaterial({
  map: PUFF, color: 0xFFE7B4, transparent: true, opacity: 0,
  depthWrite: false, blending: THREE.AdditiveBlending }));
youGlow.scale.setScalar(1.7);
youRing.add(youMark, youGlow);
youRing.renderOrder = 30;
scene.add(youRing);

function updateYouRing(dt){
  const want = (photo.phase === 'approach' || photo.phase === 'snap') ? 1 : 0;
  const m = youMark.material;
  m.opacity = smoothDamp(m.opacity, want, 5, dt);
  youGlow.material.opacity = m.opacity * 0.55;
  if (m.opacity < 0.01){ youRing.visible = false; return; }
  youRing.visible = true;
  youRing.position.copy(you.fz.root.position);
  youRing.position.y += you.fz.metrics.crownY + 0.55 + Math.sin(clock * 3.4) * 0.11;
  youMark.rotation.y += dt * 1.9;
  m.color.set(T.col); youGlow.material.color.set(T.col);
}

/* --- confetti burst at the line ------------------------------------------ */
const confetti = (() => {
  const N = 220;
  const pos = new Float32Array(N * 3), col = new Float32Array(N * 3), sz = new Float32Array(N);
  const vel = [], life = new Float32Array(N);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  g.setAttribute('aSize', new THREE.BufferAttribute(sz, 1));
  const m = new THREE.ShaderMaterial({
    uniforms: { uTex: { value: PUFF } }, transparent: true, depthWrite: false,
    vertexShader: `attribute float aSize; varying vec3 vC;
      void main(){ vC = color; vec4 mv = modelViewMatrix * vec4(position,1.0);
        gl_PointSize = aSize * 300.0 / max(-mv.z, 1.0);
        gl_Position = projectionMatrix * mv; }`,
    fragmentShader: `uniform sampler2D uTex; varying vec3 vC;
      void main(){ float a = texture2D(uTex, gl_PointCoord).a;
        if (a < 0.08) discard; gl_FragColor = vec4(vC, a); }`,
    vertexColors: true
  });
  for (let i = 0; i < N; i++) vel.push(new THREE.Vector3());
  const pts = new THREE.Points(g, m);
  pts.frustumCulled = false; pts.visible = false;
  scene.add(pts);
  return { pts, g, pos, col, sz, vel, life, N, live: false };
})();

function burstConfetti(at){
  const C = confetti, tint = new THREE.Color();
  const hues = [0xF2C2CB, 0xB6DEC4, 0xF3DC9B, 0xC0C8EE, 0xCFC0E4, 0xFFF3DE];
  for (let i = 0; i < C.N; i++){
    C.pos[i*3]   = at.x + (rnd() - .5) * 1.2;
    C.pos[i*3+1] = at.y + 1.0 + rnd() * 0.8;
    C.pos[i*3+2] = at.z + (rnd() - .5) * 1.2;
    const sp = 3.5 + rnd() * 7.5, a = rnd() * 6.283, e = 0.35 + rnd() * 0.9;
    C.vel[i].set(Math.cos(a) * sp * 0.6, sp * e, Math.sin(a) * sp * 0.6);
    tint.set(hues[(rnd() * hues.length) | 0]);
    C.col[i*3] = tint.r; C.col[i*3+1] = tint.g; C.col[i*3+2] = tint.b;
    C.sz[i] = 0.10 + rnd() * 0.16;
    C.life[i] = 2.2 + rnd() * 1.6;
  }
  C.g.attributes.position.needsUpdate = true;
  C.g.attributes.color.needsUpdate = true;
  C.g.attributes.aSize.needsUpdate = true;
  /* run it forward a beat so the freeze-frame catches a spray, not a clump */
  C.pts.visible = true; C.live = true;
  for (let k = 0; k < 14; k++) updateConfetti(0.018);
}

function updateConfetti(dt){
  const C = confetti;
  if (!C.live) return;
  let alive = 0;
  for (let i = 0; i < C.N; i++){
    if (C.life[i] <= 0) continue;
    alive++;
    C.life[i] -= dt;
    C.vel[i].y -= 7.2 * dt;
    C.vel[i].multiplyScalar(1 - 1.15 * dt);
    C.pos[i*3]   += C.vel[i].x * dt;
    C.pos[i*3+1] += C.vel[i].y * dt;
    C.pos[i*3+2] += C.vel[i].z * dt;
    if (C.life[i] < 0.7) C.sz[i] *= 0.965;
  }
  C.g.attributes.position.needsUpdate = true;
  C.g.attributes.aSize.needsUpdate = true;
  if (!alive){ C.live = false; C.pts.visible = false; }
}

/* --- the sequence --------------------------------------------------------- */
function armPhoto(){
  let rival = null, best = 1e9;
  for (const r of racers){
    if (r === you) continue;
    const d = Math.abs(r.dist - you.dist);
    if (d < best){ best = d; rival = r; }
  }
  photo.rival = rival; photo.gap = best;
  photo.close = best < 7 ? 2 : best < 20 ? 1 : 0;
  photo.phase = 'approach'; photo.t = 0; photo.snapped = false;
  scaleTarget = [0.58, 0.38, 0.26][photo.close];
  document.body.classList.add('cinema');
  if (photo.close) el('photoTag').textContent = photo.close === 2 ? 'PHOTO FINISH' : 'CLOSE FINISH';
  el('photoTag').classList.toggle('on', photo.close > 0);
  audio.duck(true, photo.close);
}

function snapPhoto(){
  photo.phase = 'snap'; photo.t = 0; photo.snapped = true;
  scaleTarget = 0.012;

  const r = photo.rival;
  let m = 0;
  if (r){
    m = r.finished ? (you.finishTime - r.finishTime)
                   : -((FINISH_DIST - r.dist) / Math.max(r.vel, 1));
  }
  photo.margin = m;
  const a = Math.abs(m);
  const word = a < 0.05 ? 'BY A WHISKER' : a < 0.12 ? 'BY A NOSE'
             : a < 0.35 ? 'BY A STRIDE'  : null;
  const who = m < 0 ? 'MUSE' : (r ? r.cfg.name.toUpperCase() : '');
  el('photoWho').textContent = m < 0 ? 'MUSE TAKES IT' : who + ' TAKES IT';
  el('photoWho').style.color = m < 0 ? '#FFF4DF' : '#' + (r ? r.cfg.fur.toString(16).padStart(6,'0') : 'fff');
  el('photoBy').textContent = word ? word : 'BY ' + a.toFixed(2) + 's';
  el('photoGap').textContent = word ? a.toFixed(3) + ' SECONDS' : '';

  document.body.classList.add('snap');
  flashFrame();
  audio.shutter();
  audio.duck(true, 2);
  burstConfetti(you.fz.root.position);
  if (you.place === 1) breakTape();
}

function endPhoto(){
  photo.phase = 'settle'; photo.t = 0;
  scaleTarget = 1;
  document.body.classList.remove('snap', 'cinema');
  document.body.classList.add('afterglow');
  el('photoTag').classList.remove('on');
  audio.duck(false, 0);
  audio.fanfare(you.place === 1);
}

function updatePhoto(dt){
  if (photo.phase === 'off'){ el('photoRef').style.opacity = '0'; return; }
  photo.t += dt;
  if (photo.phase === 'approach'){
    /* let the slow motion land first, then swing to the rig for the last 24m */
    const swing = (FINISH_DIST - you.dist) < 17 || you.finished ? 1 : 0;
    photo.blend = smoothDamp(photo.blend, swing, 3.4, dt);
    /* never strand the player in slow-mo if something goes wrong */
    if (photo.t > 14){ photo.phase = 'off'; scaleTarget = 1; document.body.classList.remove('cinema'); }
  } else if (photo.phase === 'snap'){
    photo.blend = 1;
    if (photo.t > 1.85) endPhoto();
  } else if (photo.phase === 'settle'){
    photo.blend = smoothDamp(photo.blend, 0, 2.6, dt);
    if (photo.t > 0.85 && state === 'race') showResults();
  }
  drawFinishRef();
}

/* Project the real finish line into screen space so the freeze-frame carries a
   genuine reference, not a decorative stripe pasted down the middle.          */
const _refA = new THREE.Vector3(), _refB = new THREE.Vector3();
function drawFinishRef(){
  const svg = el('photoRef');
  if (photo.phase !== 'snap'){ svg.style.opacity = '0'; return; }
  _refA.copy(LINE.pos).addScaledVector(LINE.right, you.lane * 0.30).setY(LINE.pos.y - 0.15);
  _refB.copy(_refA).setY(LINE.pos.y + 3.4);
  _refA.project(camera); _refB.project(camera);
  const w = innerWidth, h = innerHeight;
  const ax = (_refA.x * .5 + .5) * w, ay = (-_refA.y * .5 + .5) * h;
  const bx = (_refB.x * .5 + .5) * w, by = (-_refB.y * .5 + .5) * h;
  const ln = svg.firstElementChild;
  ln.setAttribute('x1', ax); ln.setAttribute('y1', ay);
  ln.setAttribute('x2', bx); ln.setAttribute('y2', by);
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  svg.style.opacity = '1';
}

function flashFrame(){
  const f = el('flash');
  f.style.animation = 'none'; void f.offsetWidth;
  f.style.animation = 'flash .42s ease-out forwards';
}

function resetPhoto(){
  photo.phase = 'off'; photo.t = 0; photo.blend = 0; photo.rival = null; photo.snapped = false;
  timeScale = 1; scaleTarget = 1;
  tapeBroken = false; tapeFade = 0; tape.visible = false;
  for (const h of tapeHalves){
    h.vy = 0; h.spin = 0; h.pivot.visible = true;
    h.pivot.rotation.set(0, 0, 0); h.pivot.position.y = 0;
  }
  confetti.live = false; confetti.pts.visible = false;
  youMark.material.opacity = 0; youGlow.material.opacity = 0; youRing.visible = false;
  document.body.classList.remove('cinema', 'snap', 'afterglow');
  el('photoTag').classList.remove('on');
  el('photoRef').style.opacity = '0';
  audio.duck(false, 0);
}

/* ============================== SIMULATION ============================== */
const camPos = new THREE.Vector3(), camLook = new THREE.Vector3();
const tmpV = new THREE.Vector3(), tmpV2 = new THREE.Vector3(), tmpV3 = new THREE.Vector3();
let camInit = false, shake = 0, camBack = 7.1, camHigh = 2.95;
const _camF = mkFrame(), _camL = mkFrame();
const _photoPos = new THREE.Vector3(), _photoLook = new THREE.Vector3();

function simulate(dt){
  /* ---- player ---- */
  if (!you.finished){
    you.vel = Math.max(0, you.vel - you.vel * DRAG * dt * (1 + you.vel * 0.012));
    you.dist += you.vel * dt;
  } else {
    you.vel = smoothDamp(you.vel, 0, 1.6, dt);
    you.dist += you.vel * dt;
  }

  /* ---- CPUs ---- */
  const prog = p => p.dist;
  for (let i = 1; i < racers.length; i++){
    const r = racers[i];
    if (r.finished){
      r.vel = smoothDamp(r.vel, 0, 1.6, dt);
      r.dist += r.vel * dt;
      continue;
    }
    const lapT = clamp(r.dist / FINISH_DIST, 0, 1);
    let target = (r.base
      + Math.sin(raceTime * r.surgeF * 6.28 + r.surgePh) * r.surgeA
      + r.fade * (0.5 - lapT) * 2) * T.cpu;

    /* Asymmetric, and that asymmetry is the whole late-game. CHASE grows every
       tempo, so a lead gets hunted harder the deeper you are. MERCY — the help
       you get when you drop back — all but vanishes by PRESTO. Early mistakes
       are forgiven; late ones are not. */
    const gap = you.dist - r.dist;
    target += clamp(gap * 0.058, -T.mercy, T.chase);

    /* corners cost a touch of speed */
    target -= Math.abs(curvatureAt(r.dist)) * 5.5;

    r.stumbleT -= dt;
    if (r.stumbleT <= 0){ r.stumble = .5; r.stumbleT = 7 + rnd() * 11; }
    if (r.stumble > 0){ r.stumble -= dt; target *= 0.72; }

    r.vel = smoothDamp(r.vel, Math.max(4, target), 1.5, dt);
    r.dist += r.vel * dt;
  }

  /* ---- finish detection ---- */
  for (const r of racers){
    if (!r.finished && r.dist >= FINISH_DIST){
      r.finished = true;
      r.finishTime = raceTime;
      r.place = racers.filter(x => x.finished).length;
      r.smile = 1;
      if (r === you) onPlayerFinish();
      if (r.place === 1) breakTape(r);
    }
  }
}

function poseRacers(dt){
  for (const r of racers){
    const f = FR;
    frameAt(r.dist, f);

    /* lane + a little life in the line */
    r.sway += dt * (0.7 + r.vel * 0.02);
    const lane = r.lane + Math.sin(r.sway) * (r.cfg.you ? 0.10 : 0.34);
    tmpV.copy(f.pos).addScaledVector(f.right, lane);

    const sp01 = clamp(r.vel / MAXSPEED, 0, 1);

    /* stride phase — stride length grows with speed so legs never blur */
    const strideLen = 2.25 + r.vel * 0.082;
    r.phase += (r.vel / strideLen) * dt * Math.PI * 2;

    let swing = clamp(sp01 * 1.5, 0, 1);
    if (r.vel < 1.6){
      /* idling on the line: a slow shift of weight, not a dead statue */
      const b = clock * 1.25 + r.sway;
      r.fz.shared.uPhase.value = Math.sin(b) * 0.62;
      swing = Math.max(swing, 0.17);
      r.hop = Math.max(r.hop * Math.exp(-6 * dt), 0.012 + Math.abs(Math.sin(b)) * 0.035);
    } else {
      r.fz.shared.uPhase.value = r.phase;
      r.hop = Math.max(r.hop * Math.exp(-6 * dt), Math.abs(Math.sin(r.phase)) * (0.06 + sp01 * 0.20));
    }

    r.fz.root.position.copy(tmpV);
    r.fz.root.position.y += r.hop;
    r.fz.root.rotation.y = Math.atan2(f.tan.x, f.tan.z);

    /* dip for the line, the way a sprinter throws for the tape */
    const toLine = FINISH_DIST - r.dist;
    const wantLunge = (photo.phase !== 'off' && toLine < 4.5 && toLine > -3.5)
      ? clamp(1 - Math.abs(toLine - 0.5) / 4.0, 0, 1) : 0;
    r.lunge = smoothDamp(r.lunge, wantLunge, 9, dt);
    r.fz.body.scale.set(1 - r.lunge * 0.05, 1 - r.lunge * 0.07, 1 + r.lunge * 0.15);

    const targetLean = sp01 * 0.30 + (r.stumble > 0 ? -0.18 : 0) + r.lunge * 0.42;
    r.lean = smoothDamp(r.lean, targetLean, 6, dt);
    const curv = curvatureAt(r.dist);
    r.bank = smoothDamp(r.bank, clamp(-curv * r.vel * 0.55, -0.34, 0.34), 5, dt);
    r.fz.tilt.rotation.x = r.lean;
    r.fz.tilt.rotation.z = r.bank;

    r.fz.shared.uSwing.value = smoothDamp(r.fz.shared.uSwing.value, swing, 5, dt);

    /* shadow hugs the ground while the body hops */
    r.fz.shadow.position.y = 0.10 - r.hop;
    r.fz.shadow.scale.setScalar(clamp(1 - r.hop * 0.55, .55, 1.1));
    r.fz.shadow.material.opacity = 0.44 * clamp(1 - r.hop * 0.7, .3, 1);

    /* blinking + expression */
    r.blinkT -= dt;
    if (r.blinkT <= 0){ r.blinkT = 1.6 + rnd() * 5.2; r.blink = 1; }
    r.blink = Math.max(0, r.blink - dt * 7.5);
    r.fz.faceU.uBlink.value = Math.sin(clamp(r.blink, 0, 1) * Math.PI);
    const wantSmile = r.finished ? 1 : clamp((sp01 - 0.45) * 1.9, 0, 1);
    r.smile = smoothDamp(r.smile, wantSmile, 4, dt);
    r.fz.faceU.uSmile.value = r.smile;
  }
}

function updateCamera(dt){
  if (state === 'title'){
    const a = clock * 0.19;
    tmpV3.copy(racers[2].fz.root.position).lerp(racers[3].fz.root.position, 0.5);
    camPos.set(tmpV3.x + Math.cos(a) * 9.6, tmpV3.y + 3.1 + Math.sin(a * .7) * 0.9, tmpV3.z + Math.sin(a) * 9.6);
    camera.position.copy(camPos);
    camLook.copy(tmpV3).y += 1.15;
    camera.lookAt(camLook);
    camera.fov = 44; camera.updateProjectionMatrix();
    return;
  }

  if (state === 'finish' && celebrate > 0 && photo.blend < 0.35){
    const a = clock * 0.55;
    tmpV.copy(you.fz.root.position);
    camPos.set(tmpV.x + Math.cos(a) * 6.2, tmpV.y + 3.0, tmpV.z + Math.sin(a) * 6.2);
    camera.position.lerp(camPos, 1 - Math.exp(-4 * dt));
    tmpV3.copy(tmpV); tmpV3.y += 1.25;
    camLook.lerp(tmpV3, 1 - Math.exp(-6 * dt));
    camera.lookAt(camLook);
    camera.fov = smoothDamp(camera.fov, 46, 3, dt);
    camera.updateProjectionMatrix();
    return;
  }

  const sp01 = clamp(you.vel / MAXSPEED, 0, 1);
  camBack = smoothDamp(camBack, 7.1 + sp01 * 2.6, 2.6, dt);
  camHigh = smoothDamp(camHigh, 2.95 + sp01 * 0.8, 2.6, dt);

  frameAt(you.dist - camBack, _camF);
  tmpV.copy(_camF.pos).addScaledVector(_camF.right, you.lane * 0.92);
  tmpV.y += camHigh;

  frameAt(you.dist + 6.0 + sp01 * 5.0, _camL);
  tmpV2.copy(_camL.pos).addScaledVector(_camL.right, you.lane);
  tmpV2.y += 1.15;

  /* Trackside finish rig: downstream of the line and off to the side, low and
     level with the tape, looking back up the track. Blended in over the last
     few metres so it reads as a camera move rather than a jump cut.          */
  if (photo.blend > 0.001){
    const b = photo.blend * photo.blend * (3 - 2 * photo.blend);
    const push = photo.phase === 'snap' ? Math.min(1, photo.t * 0.55) : 0;
    _photoPos.copy(LINE.pos)
      .addScaledVector(LINE.right, 9.0 - push * 0.7)
      .addScaledVector(LINE.tan,   7.0 - push * 0.8);
    _photoPos.y = LINE.pos.y + 1.95;
    _photoLook.copy(LINE.pos)
      .addScaledVector(LINE.tan, -0.5)
      .addScaledVector(LINE.right, you.lane * 0.30);
    _photoLook.y = LINE.pos.y + 1.05;
    tmpV.lerp(_photoPos, b);
    tmpV2.lerp(_photoLook, b);
  }

  if (!camInit){ camera.position.copy(tmpV); camLook.copy(tmpV2); camInit = true; }

  const k = state === 'countdown' ? 6 : photo.blend > 0.01 ? 7 : 16;
  camera.position.lerp(tmpV, 1 - Math.exp(-k * dt));
  camLook.lerp(tmpV2, 1 - Math.exp(-(photo.blend > 0.01 ? 6 : 10) * dt));

  const tShake = (state === 'race' ? T.shake : 1);
  shake = smoothDamp(shake, sp01 * sp01 * 0.10 * tShake + tempoJolt * 0.16, 4, dt);
  tempoJolt = Math.max(0, tempoJolt - dt * 1.6);
  camera.position.x += Math.sin(clock * 21) * shake;
  camera.position.y += Math.sin(clock * 17.3) * shake * 0.8;

  camera.lookAt(camLook);
  camera.rotation.z += -you.bank * 0.35 * (1 - photo.blend);
  const wantFov = lerp(57 + sp01 * 13, 34, photo.blend);
  camera.fov = smoothDamp(camera.fov, wantFov, photo.phase === 'snap' ? 2.2 : 4, dt);
  camera.updateProjectionMatrix();
}

/* ============================== HUD UPDATE ============================== */
let hudT = 0;
function updateHUD(dt){
  hudT += dt;

  const order = racers.slice().sort((a, b) =>
    (a.finished && b.finished) ? a.finishTime - b.finishTime : b.dist - a.dist);

  if (hudT > 0.07){
    hudT = 0;
    order.forEach((r, i) => {
      r.row.querySelector('.pos').textContent = (i + 1);
      const gap = r.dist - you.dist;
      r.row.querySelector('.gap').textContent =
        r === you ? '-' : (gap > 0 ? '+' : '') + gap.toFixed(0) + 'm';
      r.row.style.order = i;
      boardRows.appendChild(r.row);
    });
    racers.forEach((r, i) => {
      pips[i].style.left = (clamp(r.dist / FINISH_DIST, 0, 1) * 100) + '%';
    });
  }

  const myPlace = order.indexOf(you) + 1;
  el('posv').innerHTML = ['1<small>st</small>','2<small>nd</small>','3<small>rd</small>',
    '4<small>th</small>','5<small>th</small>','6<small>th</small>'][myPlace - 1] || '—';
  el('lapv').innerHTML = clamp(Math.floor(you.dist / TOTAL) + 1, 1, LAPS) + `<small>/${LAPS}</small>`;
  el('timev').textContent = raceTime.toFixed(1);

  el('speedbar').style.width = (clamp(you.vel / MAXSPEED, 0, 1) * 100) + '%';
  el('lockv').textContent = locks;

  /* The needle is the falling piece. It sweeps right in real time from the
     moment you last tapped; tap again while it is inside the band.          */
  const since = lastTap ? nowSec() - lastTap : DIAL_MAX;
  const inBand = since >= T.lo && since <= T.hi;
  el('needle').style.left = (clamp(since / DIAL_MAX, 0, 1) * 100) + '%';
  el('needle').style.background = inBand ? T.col : '#4A3B2C';
  el('cadence').style.boxShadow = inBand
    ? `0 0 0 2px ${T.col}99, 0 10px 30px rgba(74,59,44,.22)`
    : '0 10px 34px rgba(74,59,44,.22)';

  /* beat marker breathes on the metronome, lock bar fills towards the next clear */
  el('beat').style.transform = `scaleY(${(1 + beatPulse * 0.55).toFixed(2)})`;
  el('beat').style.opacity = (0.35 + beatPulse * 0.6).toFixed(2);
  const prog = streak > 0 ? (streak % LOCK_EVERY) / LOCK_EVERY : 0;
  el('lockfill').style.width = ((lockFlash > 0 ? 1 : prog) * 100) + '%';
}

/* ============================ FINISH HANDLING =========================== */
function onPlayerFinish(){
  if (photo.phase === 'approach') snapPhoto();
  else finishHold = 1.5;            // backstop if the rig never armed
}

function showResults(){
  state = 'finish';
  celebrate = 1;
  restartAt = clock + 1.1;
  const order = racers.slice().sort((a, b) =>
    (a.finished && b.finished) ? a.finishTime - b.finishTime :
    a.finished ? -1 : b.finished ? 1 : b.dist - a.dist);

  const medals = ['🥇', '🥈', '🥉', '4', '5', '6'];
  el('results').innerHTML = order.map((r, i) =>
    `<div class="rrow ${r.cfg.you ? 'me' : ''}">
       <span class="medal">${medals[i]}</span>
       <span class="dot" style="background:#${r.cfg.fur.toString(16).padStart(6,'0')}"></span>
       <span class="nm">${r.cfg.name}${r.cfg.you ? ' <small style="opacity:.55">(you)</small>' : ''}</span>
       <span class="tm">${r.finished ? r.finishTime.toFixed(2) + 's' : '—'}</span>
     </div>`).join('');

  const place = order.indexOf(you) + 1;
  const titles = __W.copy.placeTitles;
    const subs = __W.copy.placeLines;
  el('finishtitle').textContent = titles[place - 1];
  el('finishsub').innerHTML = subs[place - 1] +
    `<br><b>${(you.finished ? you.finishTime : raceTime).toFixed(2)}s</b>` +
    ` · reached <b style="color:${T.col}">${T.name}</b>` +
    ` · ${locks} lock${locks === 1 ? '' : 's'} · best run ${bestStreak} in the band`;
  el('finish').classList.remove('hide');
  reportResult(order, place);
}

/* The game runs in a sandboxed iframe with no same-origin access, so it cannot
   talk to the API itself. It posts a result up; the host verifies and stores. */
function reportResult(order, place){
  try {
    parent.postMessage({
      source: 'gamemog',
      type: 'result',
      gameId: __W.meta.id,
      place,
      finished: you.finished,
      timeMs: Math.round((you.finished ? you.finishTime : raceTime) * 1000),
      laps: LAPS,
      tempoReached: T.n,
      locks,
      bestStreak,
      field: order.map(r => ({ name: r.cfg.name, timeMs: r.finished ? Math.round(r.finishTime * 1000) : null }))
    }, '*');
  } catch (e) { /* standalone file, no host listening */ }
}

/* ================================= LOOP ================================= */
const three = new THREE.Clock();
let started = false;

function frame(){
  requestAnimationFrame(frame);
  const dt = Math.min(three.getDelta(), 0.05);   // real seconds
  clock += dt;

  /* world seconds. Slow motion is purely presentational: the stride impulse is
     scaled by the same factor (see stride()), so who wins is unchanged.       */
  timeScale = smoothDamp(timeScale, scaleTarget, photo.phase === 'snap' ? 14 : 4.5, dt);
  const sdt = dt * timeScale;
  updatePhoto(dt);

  LIGHTU.uTime.value = clock;
  sporeRate = smoothDamp(sporeRate, state === 'race' ? T.spore : 1, 1.4, dt);
  sporeTime += dt * sporeRate;
  spores.m.uniforms.uTime.value = sporeTime;
  beatPulse = Math.max(0, beatPulse - dt * 5.5);
  lockFlash = Math.max(0, lockFlash - dt * 2.2);
  tempoBannerT = Math.max(0, tempoBannerT - dt);

  /* the Hollow warms towards dusk as the tempo climbs */
  const gk = 1 - Math.exp(-1.1 * dt);
  LIGHTU.uFogCol.value.lerp(gradeFog, gk);
  LIGHTU.uLightCol.value.lerp(gradeLight, gk);
  scene.fog.color.copy(LIGHTU.uFogCol.value);
  sky.material.uniforms.uGrade.value.lerp(gradeSky, gk);
  sky.position.copy(camera.position);
  clouds.position.x = Math.sin(clock * 0.012) * 18;

  for (const l of lanternGlows){
    l.sp.material.opacity = 0.42 + Math.sin(clock * 1.7 + l.ph) * 0.13;
  }
  for (const i of islets){
    i.g.position.y = i.y0 + Math.sin(clock * i.sp + i.ph) * 1.6;
    i.g.rotation.y += dt * 0.02;
  }

  if (state === 'countdown'){
    countdown -= dt;
    const n = countdown > 2.9 ? 3 : countdown > 1.9 ? 2 : countdown > 0.9 ? 1 : 0;
    if (n !== countShown){
      countShown = n;
      audio.beep(n === 0);
      bigText(n === 0 ? 'GO!' : String(n), n === 0 ? 1.0 : 0.95);
    }
    if (countdown <= 0.9){ state = 'race'; lastTap = 0; }
  }

  if (state === 'race'){
    raceTime += sdt;

    /* ---- level up: one tempo per lap, exactly like Tetris gravity steps ---- */
    const lvl = clamp(Math.floor(you.dist / TOTAL), 0, TEMPI.length - 1);
    if (lvl !== TEMPO){ TEMPO = lvl; T = TEMPI[lvl]; onTempoUp(); }

    /* metronome stays on the wall clock — your hands never went into slow-mo */
    beatT += dt;
    if (beatT >= T.ideal){ beatT -= T.ideal; beatPulse = 1; audio.tick(); }

    /* arm the finish rig once the line is in sight */
    if (photo.phase === 'off' && !you.finished && FINISH_DIST - you.dist <= PHOTO_ARM)
      armPhoto();

    simulate(sdt);
    bestStreak = Math.max(bestStreak, streak);
    if (finishHold > 0){
      finishHold -= dt;
      if (finishHold <= 0) showResults();
    }
  } else if (state === 'countdown'){
    simulate(0);
  } else if (state === 'finish'){
    simulate(sdt * 0.35);
  }

  updateTape(dt);
  updateYouRing(dt);
  updateConfetti(sdt);
  poseRacers(sdt);
  updateCamera(dt);
  if (state !== 'title') updateHUD(dt);
  audio.setWind(clamp(you.vel / MAXSPEED, 0, 1));

  renderer.render(scene, camera);

  if (!started){
    started = true;
    try { parent.postMessage({ source: 'gamemog', type: 'ready', gameId: __W.meta.id }, '*'); } catch (e) {}
    setTimeout(() => {
      const l = document.getElementById('loading');
      l.style.transition = 'opacity .5s'; l.style.opacity = '0';
      setTimeout(() => l.remove(), 520);
    }, 180);
  }
}

/* handy for tinkering from the console */
window.MUSE = { scene, camera, renderer, racers, you, curve, TOTAL, LIGHTU, TEMPI,
                st: () => state, set: v => { state = v; },
                tempo: () => T, level: () => TEMPO, photo, scale: () => timeScale };

/* pose everything once so the title screen is populated */
poseRacers(0.016);
updateCamera(0.016);
frame();

}

})();
